/* eslint-disable @typescript-eslint/no-require-imports */
/**
 * AVenS Katalog PDF İndirici
 * Tüm kategorilerdeki PDF'leri indirir
 */

const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

const __KATALOG_URL = 'https://avenstr.com/tr/ticari-havalandirma';
const OUTPUT_DIR = path.join(__dirname, 'pdfs');

// PDF klasörünü oluştur
if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
}

// PDF indirme fonksiyonu
async function downloadPDF(url, filename) {
    return new Promise((resolve, reject) => {
        const protocol = url.startsWith('https') ? https : http;
        const filePath = path.join(OUTPUT_DIR, filename);

        console.warn(`📥 İndiriliyor: ${filename}`);

        const file = fs.createWriteStream(filePath);
        protocol.get(url, (response) => {
            response.pipe(file);
            file.on('finish', () => {
                file.close();
                console.warn(`✅ İndirildi: ${filename}`);
                resolve();
            });
        }).on('error', (err) => {
            fs.unlink(filePath, () => { });
            reject(err);
        });
    });
}

// Kategori sayfasındaki PDF'leri bul ve indir
async function downloadCategoryPDFs(page, categoryName, categoryUrl) {
    console.warn(`\n🔍 Kategori: ${categoryName}`);
    console.warn(`   URL: ${categoryUrl}`);

    try {
        await page.goto(categoryUrl, {
            waitUntil: 'networkidle2',
            timeout: 30000
        });

        await page.waitForTimeout(2000);

        // PDF linklerini bul
        const pdfLinks = await page.evaluate(() => {
            const links = [];
            // PDF içeren tüm linkleri bul
            const allLinks = document.querySelectorAll('a[href*=".pdf"], a[href*="PDF"]');

            allLinks.forEach(link => {
                const href = link.getAttribute('href');
                if (href && (href.includes('.pdf') || href.includes('.PDF'))) {
                    // Tam URL'yi oluştur
                    const fullUrl = href.startsWith('http') ? href :
                        href.startsWith('/') ? `https://avenstr.com${href}` :
                            `https://avenstr.com/${href}`;

                    // Link metnini veya başka bir tanımlayıcıyı al
                    const text = link.textContent?.trim() ||
                        link.querySelector('img')?.alt ||
                        'unnamed';

                    links.push({
                        url: fullUrl,
                        text: text
                    });
                }
            });

            return links;
        });

        console.warn(`   Bulunan PDF sayısı: ${pdfLinks.length}`);

        // Her PDF'i indir
        for (let i = 0; i < pdfLinks.length; i++) {
            const { url, text } = pdfLinks[i];

            // Dosya adını oluştur
            const __urlParts = url.split('/');
            const originalFilename = __urlParts[__urlParts.length - 1];
            const sanitizedCategory = categoryName.replace(/[^a-zA-Z0-9]/g, '_');
            const filename = `${sanitizedCategory}_${i + 1}_${originalFilename}`;

            try {
                await downloadPDF(url, filename);
            } catch (error) {
                console.error(`   ❌ Hata (${filename}):`, error.message);
            }

            // Rate limiting
            await new Promise(resolve => setTimeout(resolve, 500));
        }

        return pdfLinks.length;

    } catch (error) {
        console.error(`   ❌ Kategori hatası: ${error.message}`);
        return 0;
    }
}

async function main() {
    console.warn('🚀 AVenS PDF İndirici Başlatılıyor...\n');
    console.warn(`📁 İndirme klasörü: ${OUTPUT_DIR}\n`);

    const browser = await puppeteer.launch({
        headless: false, // Görsel olarak takip etmek için
        defaultViewport: { width: 1920, height: 1080 }
    });

    const page = await browser.newPage();

    // Ana kataloglar sayfasına git
    console.warn('📖 Kataloglar sayfası açılıyor...');
    await page.goto('https://avenstr.com/kataloglar', {
        waitUntil: 'networkidle2',
        timeout: 30000
    });

    await page.waitForTimeout(2000);

    // Kategorileri ve linklerini al
    const categories = await page.evaluate(() => {
        const cats = [];

        // Sol menüdeki kategori linklerini bul
        const menuLinks = document.querySelectorAll('.kategoriBaslik a, .category-menu a, ul.list-unstyled a');

        menuLinks.forEach(link => {
            const text = link.textContent?.trim();
            const href = link.getAttribute('href');

            if (text && href && !href.includes('#')) {
                const fullUrl = href.startsWith('http') ? href :
                    href.startsWith('/') ? `https://avenstr.com${href}` :
                        `https://avenstr.com/${href}`;

                cats.push({
                    name: text,
                    url: fullUrl
                });
            }
        });

        return cats;
    });

    console.warn(`\n✅ ${categories.length} kategori bulundu:\n`);
    categories.forEach((cat, i) => {
        console.warn(`   ${i + 1}. ${cat.name}`);
    });

    // Her kategori için PDF'leri indir
    let totalPDFs = 0;
    for (const category of categories) {
        const count = await downloadCategoryPDFs(page, category.name, category.url);
        totalPDFs += count;
    }

    console.warn(`\n${'='.repeat(60)}`);
    console.warn(`✅ Tamamlandı!`);
    console.warn(`📊 Toplam ${totalPDFs} PDF indirildi`);
    console.warn(`📁 Konum: ${OUTPUT_DIR}`);
    console.warn('='.repeat(60));

    await browser.close();
}

main().catch(error => {
    console.error('❌ Fatal error:', error);
    process.exit(1);
});

import puppeteer from 'puppeteer';
import fs from 'fs/promises';
import path from 'path';

const BASE_URL = 'https://avensair.com';
const DELAY = 3000;

// EKSİK KATEGORİLER (1 üründen az olanlar)
const MISSING_CATEGORIES = [
  { name: 'Duvar Tipi Fanlar', url: '/duvar-tipi-fanlar' },
  { name: 'Sessiz Fanlar', url: '/sessiz-fanlar' },
  { name: 'Endüstriyel Fanlar', url: '/endustriyel-fanlar' },
  { name: 'Ex-Proof Fanlar', url: '/ex-proof-fanlar' },
  { name: 'Duman Egzoz Fanları', url: '/duman-egzoz-fanlari' },
  { name: 'Jet Fanlar', url: '/jet-fanlar' },
  { name: 'Basınçlandırma Fanları', url: '/basinclandirma-fanlari' },
  { name: 'Sığınak Fanları', url: '/siginak-fanlari' },
  { name: 'Nicotra Gebhardt', url: '/nicotra-gebhardt' },
  { name: 'Flexible Kanallar', url: '/flexible-kanallar' },
  // Eksik olanlar
  { name: 'Hava Perdeleri', url: '/hava-perdeleri' },
  { name: 'Aksesuarlar', url: '/aksesuarlar' },
  { name: 'Konut Tipi Fanlar', url: '/konut-tipi-fanlar' },
  { name: 'Kanal Tipi Fanlar', url: '/kanal-tipi-fanlar' },
  { name: 'Çatı Tipi Fanlar', url: '/cati-tipi-fanlar' },
  { name: 'Santrifüj Fanlar', url: '/santrifuj-fanlar' }
];

async function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function loadAllProducts(page) {
  console.warn('🔄 "Daha fazla" butonları kontrol ediliyor...');
  
  let clickCount = 0;
  let maxClicks = 500; // ÇOK FAZLA TIKLAMAK İÇİN
  
  while (clickCount < maxClicks) {
    try {
      const buttons = await page.$$('button, a, .btn, [role="button"]');
      let foundButton = false;
      
      for (const button of buttons) {
        const text = await page.evaluate(el => el.textContent, button);
        if (text && text.trim().toLowerCase().includes('daha fazla')) {
          const isVisible = await page.evaluate(button => {
            return button.offsetWidth > 0 && button.offsetHeight > 0 && 
                   window.getComputedStyle(button).display !== 'none';
          }, button);
          
          if (isVisible) {
            console.warn(`📱 Tık ${clickCount + 1}...`);
            
            await page.evaluate(button => {
              button.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, button);
            
            await delay(1000);
            await button.click();
            clickCount++;
            foundButton = true;
            await delay(DELAY);
            break;
          }
        }
      }
      
      if (!foundButton) {
        console.warn('✅ Tüm ürünler yüklendi');
        break;
      }
    } catch (error) {
      console.warn('⚠️ Hata:', error.message);
      break;
    }
  }
  
  console.warn(`📊 Toplam ${clickCount} kez tıklandı`);
  await delay(DELAY);
}

async function scrapeCategory(page, categoryInfo) {
  console.warn(`\n${'='.repeat(60)}`);
  console.warn(`🔍 ${categoryInfo.name}`);
  console.warn(`${'='.repeat(60)}`);
  
  const fullUrl = `${BASE_URL}${categoryInfo.url}`;
  
  try {
    await page.goto(fullUrl, { 
      waitUntil: 'networkidle2',
      timeout: 60000 
    });
    
    console.warn(`📍 Sayfa yüklendi`);
    await delay(DELAY);

    // Tüm ürünleri yükle
    await loadAllProducts(page);

    // Sayfada ürün kartlarını bul
    const products = await page.evaluate((catName) => {
      const productCards = [];
      
      // TÜM OLASI SELEKTÖRLERİ DENE
      const selectors = [
        '.urunkutu',  // AvensAir'in kullandığı class
        '.product-card',
        '.product-item', 
        '.product',
        '.card',
        '.item',
        'article',
        '[data-product]',
        '.grid-item',
        '.product-box',
        '.col-md-4',
        '.col-sm-6',
        '.col-lg-3',
        '.thumbnail',
        '.thumbnail-variant-1'
      ];
      
      let foundElements = [];
      
      for (const selector of selectors) {
        const elements = document.querySelectorAll(selector);
        if (elements.length > 0) {
          foundElements = Array.from(elements);
          console.warn(`✓ Selector ${selector} ile ${elements.length} element bulundu`);
          break;
        }
      }
      
      foundElements.forEach((element, index) => {
        try {
          const linkElement = element.tagName === 'A' ? element : element.querySelector('a');
          const titleElement = element.querySelector('h1, h2, h3, h4, h5, h6, .title, .name, .product-name, .caption h3') ||
                              linkElement;
          const imageElement = element.querySelector('img');
          const priceElement = element.querySelector('.price, .fiyat, .amount, .cost, .money');
          
          const productLink = linkElement ? linkElement.href : '';
          const productTitle = titleElement ? titleElement.textContent.trim() : 
                              linkElement ? linkElement.textContent.trim() : `Ürün ${index + 1}`;
          const productImage = imageElement ? imageElement.src : '';
          const productPrice = priceElement ? priceElement.textContent.trim() : '';
          
          // Geçerli ürün kontrolü
          if (productLink && 
              productTitle && 
              productTitle.length > 3 &&
              !productTitle.includes('404') &&
              !productTitle.includes('Sepet') &&
              !productTitle.includes('satis@')) {
            
            productCards.push({
              name: productTitle,
              category: catName,
              url: productLink,
              image_url: productImage,
              price: productPrice,
              brand: 'AVenS',
              scraped_at: new Date().toISOString()
            });
          }
        } catch (error) {
          console.warn(`Ürün parse hatası:`, error.message);
        }
      });
      
      return productCards;
    }, categoryInfo.name);
    
    console.warn(`✅ ${products.length} ürün bulundu`);
    return products;
    
  } catch (error) {
    console.error(`❌ ${categoryInfo.name} hatası:`, error.message);
    return [];
  }
}

async function main() {
  console.warn('🚀 AvensAir Eksik Kategoriler Scraper\n');
  
  const browser = await puppeteer.launch({
    headless: false,
    defaultViewport: { width: 1920, height: 1080 }
  });
  
  const page = await browser.newPage();
  
  let allProducts = [];
  const stats = {};
  
  for (const category of MISSING_CATEGORIES) {
    const products = await scrapeCategory(page, category);
    allProducts.push(...products);
    stats[category.name] = products.length;
    await delay(2000);
  }
  
  await browser.close();
  
  // Sonuçları kaydet
  const timestamp = new Date().toISOString().replace(/:/g, '-');
  const filename = `scraped-data/complete_avens_${timestamp}.json`;
  
  await fs.writeFile(
    filename,
    JSON.stringify(allProducts, null, 2),
    'utf-8'
  );
  
  // Özet
  console.warn('\n' + '='.repeat(60));
  console.warn('📊 SCRAPING TAMAMLANDI');
  console.warn('='.repeat(60));
  console.warn(`\nTOPLAM ÜRÜN: ${allProducts.length}\n`);
  
  console.warn('Kategori Dağılımı:');
  Object.entries(stats)
    .sort((a, b) => b[1] - a[1])
    .forEach(([cat, count]) => {
      console.warn(`  ${cat}: ${count}`);
    });
  
  console.warn(`\n💾 Kaydedildi: ${filename}`);
  console.warn('='.repeat(60));
}

main().catch(console.error);

