/* eslint-disable @typescript-eslint/no-require-imports */

const fs = require('fs');
const path = require('path');

// 1. Parse .env
const envPath = path.resolve(process.cwd(), '.env');
let env = {};
try {
    const data = fs.readFileSync(envPath, 'utf8');
    data.split('\n').forEach(line => {
        const match = line.match(/^([^=]+)=(.*)$/);
        if (match) {
            const key = match[1].trim();
            const value = match[2].trim().replace(/^["']|["']$/g, '');
            env[key] = value;
        }
    });
} catch (e) {
    console.error('Could not read .env file');
    process.exit(1);
}

const url = env.VITE_SUPABASE_URL;
const key = env.VITE_SUPABASE_ANON_KEY;

if (!url || !key) {
    console.error('Missing URL or KEY in .env');
    process.exit(1);
}

// 2. Fetch Categories
async function listCategories() {
    try {
        const endpoint = `${url}/rest/v1/categories?select=name,slug,level&order=level.asc,name.asc`;
        const response = await fetch(endpoint, {
            headers: {
                'apikey': key,
                'Authorization': `Bearer ${key}`
            }
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        const headers = '--- CATEGORIES ---\n';
        const rows = data.map(c => `[Level ${c.level}] ${c.name} -> slug: '${c.slug}'`).join('\n');
        fs.writeFileSync('categories.txt', headers + rows + '\n------------------');
        console.warn('Written to categories.txt');

    } catch (e) {
        console.error('Error fetching categories:', e);
    }
}

listCategories();

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.VITE_SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.VITE_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseKey) {
    process.exit(1);
}

const supabase = createClient(supabaseUrl, supabaseKey);

async function probe() {
    const candidates = ['exec_sql', 'execute_sql', 'run_sql', 'exec'];

    for (const fn of candidates) {
        console.warn(`Probing rpc('${fn}')...`);
        const { data, error } = await supabase.rpc(fn, { query: 'SELECT 1' });
        // Note: Parameter name might be 'sql', 'query', 'command' etc. 
        // This is a hail mary.

        // Try with 'sql' param just in case
        const { data: data2, error: error2 } = await supabase.rpc(fn, { sql: 'SELECT 1' });

        if (!error || !error2) {
            console.warn(`✅ FOUND FUNCTION: ${fn}`);
            process.exit(0);
        } else {
            console.warn(`❌ ${fn} failed:`, error?.message || error2?.message);
        }
    }
    console.warn('No SQL execution function found.');
}

probe();

