Deno.serve(async (req) => {
  const cors = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  } as Record<string,string>

  if (req.method === 'OPTIONS') return new Response(null, { status: 200, headers: cors })

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')
    const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
    if (!supabaseUrl || !serviceRoleKey) {
      return new Response(JSON.stringify({ error: 'CONFIG_MISSING' }), { status: 500, headers: { ...cors, 'Content-Type':'application/json' } })
    }

    let _id: string | null = null
    let conv: string | null = null
    if (req.method === 'POST') {
      const body = await req.json().catch(()=>null)
      id = body?.id || null
      conv = body?.conv || null
    } else {
      const url = new URL(req.url)
      id = url.searchParams.get('id')
      conv = url.searchParams.get('conv')
    }

    // RPC ile listeleme
    let limit = 10
    try { const url = new URL(req.url); const l = url.searchParams.get('limit'); if (l) limit = Math.max(1, Math.min(100, parseInt(l))) } catch {}
    const rpcListUrl = `${supabaseUrl}/rest/v1/rpc/fn_admin_get_orders`
    const listBody: { _p_id: string | null; p_conv: string | null; p_limit: number; p_status?: string | null } = { _p_id: id, p_conv: conv, p_limit: limit }
    if (!id && !conv) listBody.p_status = 'pending'; else listBody.p_status = null

    const listResp = await fetch(rpcListUrl, {
      method: 'POST',
      headers: { Authorization: `Bearer ${serviceRoleKey}`, apikey: serviceRoleKey, 'Content-Type':'application/json' },
      body: JSON.stringify(listBody)
    })
    if (!listResp.ok) {
      const text = await listResp.text().catch(()=>'' )
      return new Response(JSON.stringify({ ok:false, httpStatus: listResp.status, rpcListUrl, body:text }), { status: 200, headers: { ...cors, 'Content-Type':'application/json' } })
    }
    const orders = await listResp.json().catch(()=>[])
    if (!Array.isArray(orders) || orders.length === 0) {
      return new Response(JSON.stringify({ ok:false, processed:0, rpcListUrl, message:'no orders found' }), { status: 200, headers: { ...cors, 'Content-Type':'application/json' } })
    }

    // Callback üzerinden doğrula (SDK'yı burada kullanma). Callback hem İyzico ile konuşur hem DB'yi günceller.
    const fnHost = (() => { const su = supabaseUrl!; try { const host = new URL(su).host; const ref = host.split('.')[0]; return `https://${ref}.functions.supabase.co`; } catch { return '' } })();

    const results: Array<Record<string, unknown>> = []
    for (const o of orders) {
      const token = o?.payment_token || null
      if (!token) {
        results.push({ _id:o.id, conversation_id:o.conversation_id, skipped:'no_token' })
        continue
      }

      try {
        const cbUrl = `${fnHost}/iyzico-callback`
        const cbResp = await fetch(cbUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            // Add Authorization header to satisfy verify_jwt when enabled
            Authorization: `Bearer ${serviceRoleKey}`,
            apikey: serviceRoleKey
          },
          body: JSON.stringify({ token, conversationId: o.conversation_id, orderId: o.id })
        })
        const cbJson = await cbResp.json().catch(()=>({}))
        const st = cbJson?.status || 'pending'
        results.push({ _id:o.id, conversation_id:o.conversation_id, status: st, from:'callback' })
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e ?? '')
        results.push({ _id:o.id, conversation_id:o.conversation_id, error: msg })
      }
    }

    return new Response(JSON.stringify({ ok:true, processed: results.length, results }), { status: 200, headers: { ...cors, 'Content-Type':'application/json' } })
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e ?? '')
    return new Response(JSON.stringify({ error: msg }), { status: 500, headers: { ...cors, 'Content-Type':'application/json' } })
  }
})

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4'

Deno.serve(async (req) => {
  const cors = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  } as Record<string,string>

  if (req.method === 'OPTIONS') return new Response(null, { status: 200, headers: cors })

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')
    const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
    const anonKey = Deno.env.get('SUPABASE_ANON_KEY')
    if (!supabaseUrl || !serviceRoleKey || !anonKey) {
      return new Response(JSON.stringify({ error: 'CONFIG_MISSING' }), { status: 500, headers: { ...cors, 'Content-Type':'application/json' } })
    }

    const authHeader = req.headers.get('Authorization')
    if (!authHeader) {
      return new Response(JSON.stringify({ error: 'unauthenticated' }), { status: 401, headers: { ...cors, 'Content-Type':'application/json' } })
    }

    const supabaseUser = createClient(supabaseUrl, anonKey, { global: { headers: { Authorization: authHeader } } })
    const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey)

    const { data: userRes, error: userErr } = await supabaseUser.auth.getUser()
    if (userErr || !userRes?.user) {
      return new Response(JSON.stringify({ error: 'unauthorized' }), { status: 401, headers: { ...cors, 'Content-Type':'application/json' } })
    }

    const { data: profile, error: profErr } = await supabaseAdmin.from('user_profiles').select('role').eq('id', userRes.user.id).maybeSingle()
    const userRole = profile?.role as string | undefined
    if (profErr || !userRole || !['admin', 'superadmin'].includes(userRole)) {
      return new Response(JSON.stringify({ error: 'forbidden' }), { status: 403, headers: { ...cors, 'Content-Type':'application/json' } })
    }

    let _id: string | null = null
    let conv: string | null = null
    try {
      const url = new URL(req.url)
      id = url.searchParams.get('id')
      conv = url.searchParams.get('conv')
    } catch { /* ignore parse error */ }

    if ((!id && !conv) && (req.method === 'POST' || req.method === 'PUT')) {
      const body = await req.json().catch(()=>null)
      id = body?.id || null
      conv = body?.conv || null
    }

    if (!id && !conv) {
      return new Response(JSON.stringify({ error: 'MISSING_ID_OR_CONV' }), { status: 400, headers: { ...cors, 'Content-Type':'application/json' } })
    }

    const rpcUrl = `${supabaseUrl}/rest/v1/rpc/fn_admin_get_orders`
    const body = { _p_id: id, p_conv: conv, p_status: null, p_limit: 1 }
    const resp = await fetch(rpcUrl, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${serviceRoleKey}`,
        apikey: serviceRoleKey,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(body)
    })

    if (!resp.ok) {
      const text = await resp.text().catch(()=>'' )
      return new Response(JSON.stringify({ ok:false, httpStatus: resp.status, rpcUrl, body:text }), { status: 200, headers: { ...cors, 'Content-Type':'application/json' } })
    }

    const json = await resp.json().catch(()=>[])
    const row = Array.isArray(json) ? json[0] : null
    return new Response(JSON.stringify({ ok: !!row, rpcUrl, row }), { status: 200, headers: { ...cors, 'Content-Type':'application/json' } })
  } catch (e: unknown) {
    const err = e as Error
    return new Response(JSON.stringify({ error: String(err.message || err) }), { status: 500, headers: { ...cors, 'Content-Type':'application/json' } })
  }
})

import { serve } from "https://deno.land/std@0.168.0/http/server.ts"

interface DeliveryRequest {
  _order_id: string
  customer_email?: string
  customer_name?: string
  order_number?: string
}

function render(tpl: string, data: Record<string, unknown>) {
  return tpl.replace(/{{(\w+)}}/g, (_m, k) => String(data[k] ?? ''))
}

async function loadTemplate() {
  try {
    const url = new URL('./templates/email/delivered.html', import.meta.url)
    return await Deno.readTextFile(url)
  } catch {
    return null
  }
}

serve(async (req) => {
  const origin = req.headers.get('origin') ?? '*'
  const cors = {
    'Access-Control-Allow-Origin': origin,
    'Vary': 'Origin',
    'Access-Control-Allow-Headers': req.headers.get('access-control-request-headers') ?? 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': req.headers.get('access-control-request-method') ?? 'POST, OPTIONS',
    'Access-Control-Max-Age': '86400',
  }

  if (req.method === 'OPTIONS') return new Response(null, { status: 200, headers: cors })
  if (req.method !== 'POST') return new Response(JSON.stringify({ error: 'method_not_allowed' }), { status: 405, headers: { ...cors, 'Content-Type': 'application/json' } })

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL') || ''
    const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
    const resendApiKey = Deno.env.get('RESEND_API_KEY') || ''
    const emailFrom = Deno.env.get('EMAIL_FROM') || 'VentHub <onboarding@resend.dev>'

    const body = await req.json().catch(()=>({})) as DeliveryRequest
    let { _order_id, customer_email, customer_name, order_number } = body
    if (!_order_id) return new Response(JSON.stringify({ error: 'missing_fields', missing: ['_order_id'] }), { status: 400, headers: { ...cors, 'Content-Type': 'application/json' } })

    // Derive info if missing
    if ((!customer_email || !customer_name || !order_number) && supabaseUrl && serviceKey) {
      const o = await fetch(`${supabaseUrl}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(_order_id)}&select=order_number,customer_name,customer_email`, {
        headers: { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey }
      })
      if (o.ok) {
        const arr = await o.json().catch(()=>[])
        const row = Array.isArray(arr) ? arr[0] : null
        if (row) {
          order_number = order_number || row.order_number
          customer_name = customer_name || row.customer_name
          customer_email = customer_email || row.customer_email
        }
      }
    }

    if (!customer_email || !customer_name) {
      return new Response(JSON.stringify({ error: 'customer_info_missing' }), { status: 400, headers: { ...cors, 'Content-Type': 'application/json' } })
    }

    const prettyOrderNo = order_number ? `#${order_number.split('-')[1]}` : `#${_order_id.slice(-8).toUpperCase()}`
    const subject = `Siparişiniz teslim edildi - ${prettyOrderNo}`

    let html = (await loadTemplate()) || ''
    if (!html) {
      html = [
        '<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">',
        '<h2 style="color: #2563eb;">Teslimat Tamamlandı</h2>',
        `<p>Merhaba <strong>${customer_name}</strong>,</p>`,
        `<p><strong>${prettyOrderNo}</strong> numaralı siparişiniz başarıyla teslim edilmiştir.</p>`,
        '<p>Herhangi bir sorunuz olursa bizimle iletişime geçebilirsiniz.</p>',
        '<p>Teşekkürler,<br><strong>VentHub Ekibi</strong></p>',
        '</div>'
      ].join('')
    } else {
      html = render(html, { customer_name, order_number: prettyOrderNo })
    }

    if (!resendApiKey) {
      return new Response(JSON.stringify({ disabled: true }), { status: 200, headers: { ...cors, 'Content-Type': 'application/json' } })
    }

    const resp = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${resendApiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ from: emailFrom, to: [customer_email], subject, html })
    })
    if (!resp.ok) {
      const t = await resp.text().catch(()=> '')
      return new Response(JSON.stringify({ error: 'send_failed', body: t }), { status: 500, headers: { ...cors, 'Content-Type': 'application/json' } })
    }
    const result = await resp.json().catch(()=>({}))

    // Audit
    try {
      if (supabaseUrl && serviceKey) {
        await fetch(`${supabaseUrl}/rest/v1/shipping_email_events`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${serviceKey}`, apikey: serviceKey, Prefer: 'return=minimal' },
          body: JSON.stringify({ _order_id, email_to: customer_email, subject, provider: 'resend', provider_message_id: result?.id || null })
        })
      }
    } catch {}

    return new Response(JSON.stringify({ ok: true, _order_id, subject, result }), { status: 200, headers: { ...cors, 'Content-Type': 'application/json' } })
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e)
    return new Response(JSON.stringify({ error: msg }), { status: 500, headers: { ...cors, 'Content-Type': 'application/json' } })
  }
})

import Iyzipay from "npm:iyzipay";

// Minimal types to avoid `any` while keeping integration flexible
type CheckoutRetrieveResponse = {
  paymentStatus?: string;
  conversationId?: string;
  errorMessage?: string;
  paymentId?: string;
  cardFamily?: string;
  binNumber?: string;
  lastFourDigits?: string;
  [k: string]: unknown;
};

Deno.serve(async (req) => {
  const corsHeaders = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Max-Age": "86400",
  } as Record<string,string>;
  // İyzico callback istekleri Authorization header göndermez; 401'i engellemek için kendi CORS/anon kabulümüzü sağlar ve asla auth doğrulaması istemeyiz.

  if (req.method === "OPTIONS") {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  try {
    // İsteğin JSON bekleyip beklemediğini tespit et (uygulama içi çağrılarda JSON döneceğiz)
    const accept = (req.headers.get('accept') || '').toLowerCase()
    const wantsJson = accept.includes('application/json') || !!req.headers.get('x-client-info')

    // İyzico callback'i çoğunlukla application/x-www-form-urlencoded (token=...) gönderir.
    const contentType = (req.headers.get("content-type") || "").toLowerCase();
    let token: string | undefined;
    let conversationId: string | undefined;
    let orderId: string | undefined;

    if (contentType.includes("application/x-www-form-urlencoded")) {
      const form = await req.formData();
      token = String(form.get("token") || "");
      conversationId = form.get("conversationId")?.toString();
      orderId = form.get("orderId")?.toString();
    } else {
      const bodyJson = await req.json().catch(() => ({} as Record<string, unknown>));
      const body = bodyJson as { token?: string; conversationId?: string; orderId?: string };
      token = body?.token;
      conversationId = body?.conversationId;
      orderId = body?.orderId;
    }
    // URL query'den de parametre al (callbackUrl'e eklendi)
    let successUrl: string | null = null;
    try {
      const url = new URL(req.url);
      if (!orderId) orderId = url.searchParams.get('orderId') || undefined;
      if (!conversationId) conversationId = url.searchParams.get('conversationId') || undefined;
      successUrl = url.searchParams.get('successUrl');
    } catch {}

    // Eğer successUrl yoksa, ortamdan türet (PUBLIC_SITE_URL/FRONTEND_URL/SITE_URL)
    if (!successUrl) {
      const base = (Deno.env.get('PUBLIC_SITE_URL') || Deno.env.get('FRONTEND_URL') || Deno.env.get('SITE_URL') || '').trim();
      if (base) {
        try {
          const origin = new URL(base).origin;
          successUrl = origin + '/payment-success';
        } catch {
          successUrl = base.replace(/\/$/, '') + '/payment-success';
        }
      }
    }

    if (!token) {
      // Fallback: orderId üzerinden payment_token'ı getir ve devam et
      if (orderId) {
        try {
          const got = await fetch(`${Deno.env.get('SUPABASE_URL')}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(orderId)}&select=payment_token`, {
            headers: { Authorization: `Bearer ${Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')}`, apikey: `${Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')}` }
          })
          const arr = await got.json().catch(()=>[])
          const row = Array.isArray(arr) ? arr[0] : null
          if (row?.payment_token) token = row.payment_token
        } catch {}
      }
      if (!token) {
        // Token yine yoksa, uygulama çağrısı ise JSON, değilse frontend'e yönlendir (pending)
        if (wantsJson) {
          return new Response(JSON.stringify({ status: 'pending', reason: 'missing_token' }), { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
        } else if (successUrl) {
          try {
            const target = new URL(successUrl);
            if (orderId) target.searchParams.set('orderId', orderId);
            if (conversationId) target.searchParams.set('conversationId', conversationId);
            target.searchParams.set('status', 'pending');
            const t = target.toString();
            const html = `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=${t}"><title>Redirecting...</title></head><body><a href=${JSON.stringify(t)}>Devam etmek için tıklayın</a><script>try{window.top.location.replace(${JSON.stringify(t)});}catch(e){location.href=${JSON.stringify(t)}};</script></body></html>`;
            return new Response(html, { status: 200, headers: { ...corsHeaders, 'Content-Type': 'text/html' } });
          } catch {}
        }
        // Son çare
        return new Response(JSON.stringify({ status: 'pending' }), { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
      }
    }

    const apiKey = Deno.env.get("IYZICO_API_KEY");
    const secretKey = Deno.env.get("IYZICO_SECRET_KEY");
    const baseUrl = "https://sandbox-api.iyzipay.com"; // isteğe göre prod ayarlanabilir

    const supabaseUrl = Deno.env.get("SUPABASE_URL");
    const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

    if (!apiKey || !secretKey || !supabaseUrl || !serviceRoleKey) {
      return new Response(
        JSON.stringify({
          error: { code: "CONFIG_ERROR", message: "Environment değişkenleri eksik" },
        }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    type IyziCtorCb = new (args: { apiKey: string; secretKey: string; uri: string }) => {
      checkoutForm: {
        retrieve: (
          req: { locale: string; token: string; conversationId?: string },
          cb: (err: unknown, res: CheckoutRetrieveResponse) => void,
        ) => void;
      };
    };
    const IyziCb = Iyzipay as unknown as IyziCtorCb;
    const sdk = new IyziCb({ apiKey, secretKey, uri: baseUrl });

    const retrieveReq: { locale: string; token: string; conversationId?: string } = {
      locale: "tr",
      token,
    };
    if (conversationId) retrieveReq.conversationId = conversationId;

    // Token geldiyse hemen DB'ye yaz (denetim ve reconcile için)
    try {
      if (token && orderId) {
        await fetch(`${supabaseUrl}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(orderId)}`, {
          method: 'PATCH',
          headers: { Authorization: `Bearer ${serviceRoleKey}`, apikey: serviceRoleKey, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
          body: JSON.stringify({ payment_token: token })
        })
      }
    } catch {}

    let result: CheckoutRetrieveResponse | null = null;
    try {
      result = await new Promise<CheckoutRetrieveResponse>((resolve, reject) => {
        sdk.checkoutForm.retrieve(
          retrieveReq,
          (err: unknown, res: CheckoutRetrieveResponse) => {
            if (err) return reject(err);
            resolve(res);
          },
        );
      });
    } catch {
      // retrieve başarısızsa result=null olarak değerlendirilecek (pending)
      result = null;
    }

    // İyzico sonucu yorumla
    const paid = !!(result && result.paymentStatus === "SUCCESS");

    // Debug bilgisi hazırla
    const debugInfo: Record<string, unknown> = result ? {
      paymentStatus: result.paymentStatus ?? null,
      mdStatus: result.mdStatus ?? null,
      errorCode: result.errorCode ?? null,
      errorMessage: result.errorMessage ?? null,
      paymentId: result.paymentId ?? null,
      cardFamily: result.cardFamily ?? null,
      binNumber: result.binNumber ?? null,
      lastFourDigits: result.lastFourDigits ?? null,
      raw: result,
    } : { paymentStatus: null }

    // Supabase: venthub_orders güncelle (yalnızca kesin durumlarda yaz)
    async function patchStatus(newStatus: 'paid' | 'failed' | 'confirmed') {
      const filterById = orderId ? `id=eq.${encodeURIComponent(orderId)}` : '';
      const filterByConv = (!orderId && (result?.conversationId || conversationId)) ? `conversation_id=eq.${encodeURIComponent(result?.conversationId || conversationId!)}` : '';
      const filter = filterById || filterByConv;
      if (!filter) return null;
      const resp = await fetch(`${supabaseUrl}/rest/v1/venthub_orders?${filter}`, {
        method: "PATCH",
        headers: {
          Authorization: `Bearer ${serviceRoleKey}`,
          apikey: serviceRoleKey,
          "Content-Type": "application/json",
          Prefer: "return=representation",
        },
        body: JSON.stringify({ status: newStatus, payment_debug: debugInfo }),
      });
      return resp;
    }

    let updateOk = false;
    let _stockResult: unknown = null;
    if (paid) {
      // Önce 'paid' olarak güncellemeyi dene; constraint nedeniyle reddedilirse 'confirmed' ile tekrar dene
      let r = await patchStatus('paid');
      if (!r || !r.ok) {
        r = await patchStatus('confirmed');
      }
      updateOk = !!(r && r.ok);
      
      // Send order confirmation (best-effort, only after payment success)
      try {
        let finalOrderId: string | null = orderId || null
        if (!finalOrderId && (result?.conversationId || conversationId)) {
          const oResp = await fetch(`${supabaseUrl}/rest/v1/venthub_orders?conversation_id=eq.${encodeURIComponent(result?.conversationId || conversationId!) }&select=id`, {
            headers: { Authorization: `Bearer ${serviceRoleKey}`, apikey: serviceRoleKey }
          })
          if (oResp.ok) {
            const arr = await oResp.json().catch(()=>[])
            const row = Array.isArray(arr) ? arr[0] : null
            finalOrderId = row?.id || null
          }
        }
        if (finalOrderId) {
          await fetch(`${supabaseUrl}/functions/v1/order-confirmation`, {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${serviceRoleKey}`,
              'apikey': serviceRoleKey,
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({ _order_id: finalOrderId })
          })
        }
      } catch { /* ignore */ }
      
      // Kuponu finalize et: order row'dan coupon_code'yi al, varsa usage increment ve discount hesapla (best-effort)
      try {
        if (orderId) {
          const su = Deno.env.get('SUPABASE_URL') || ''
          const sk = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
          if (su && sk) {
            const oResp = await fetch(`${su}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(orderId)}&select=id,total_amount,coupon_code,coupon_discount`, { headers: { Authorization: `Bearer ${sk}`, apikey: sk } })
            if (oResp.ok) {
              const arr = await oResp.json().catch(()=>[])
              const row = Array.isArray(arr) ? arr[0] as { id?: string; total_amount?: number; coupon_code?: string|null; coupon_discount?: number|null } : null
              const code = (row?.coupon_code || '').trim()
              const total = Number(row?.total_amount || 0)
              if (code && total > 0) {
                // Get coupon details
                const cRes = await fetch(`${su}/rest/v1/coupons?code=eq.${encodeURIComponent(code)}&select=discount_type,discount_value,minimum_order_amount,is_active,valid_from,valid_until,usage_limit,used_count`, { headers: { Authorization: `Bearer ${sk}`, apikey: sk } })
                if (cRes.ok) {
                  const carr = await cRes.json().catch(()=>[])
                  const c = Array.isArray(carr) ? carr[0] as { discount_type?: string; discount_value?: number; minimum_order_amount?: number|null; is_active?: boolean; valid_from?: string|null; valid_until?: string|null; usage_limit?: number|null; used_count?: number|null } : null
                  if (c && c.is_active !== false) {
                    const now = Date.now()
                    const startsOk = !c.valid_from || new Date(c.valid_from).getTime() <= now
                    const endsOk = !c.valid_until || new Date(c.valid_until).getTime() > now
                    const minOk = (c.minimum_order_amount == null) || (total >= Number(c.minimum_order_amount))
                    const limitOk = (c.usage_limit == null) || (Number(c.used_count||0) < Number(c.usage_limit))
                    if (startsOk && endsOk && minOk && limitOk) {
                      let disc = 0
                      if (c.discount_type === 'percentage') disc = (total * Number(c.discount_value||0))/100
                      else disc = Number(c.discount_value||0)
                      if (disc > total) disc = total
                      const disc2 = Number(Number(disc).toFixed(2))
                      // Patch order with computed discount
                      await fetch(`${su}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(orderId)}`, {
                        method: 'PATCH',
                        headers: { Authorization: `Bearer ${sk}`, apikey: sk, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
                        body: JSON.stringify({ coupon_discount: disc2 })
                      }).catch(()=>{})
                      // Increment usage (best-effort)
                      await fetch(`${su}/rest/v1/rpc/increment_coupon_usage`, {
                        method: 'POST', headers: { Authorization: `Bearer ${sk}`, apikey: sk, 'Content-Type': 'application/json' },
                        body: JSON.stringify({ p_code: code })
                      }).catch(()=>{})
                    }
                  }
                }
              }
            }
          }
        }
      } catch { /* ignore */ }

      // Process stock reduction after successful payment - Use DB RPC (idempotent)
      try {
        if (orderId) {
          // Call centralized RPC for atomic, idempotent stock reduction
          const rpcResp = await fetch(`${supabaseUrl}/rest/v1/rpc/process_order_stock_reduction`, {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${serviceRoleKey}`,
              'apikey': serviceRoleKey,
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({ p__order_id: orderId })
          });

          if (rpcResp.ok) {
            const rpcJson = await rpcResp.json().catch(() => ({}));
            _stockResult = rpcJson || { success: true, processed_count: null, _order_id: orderId };

            // Mark stock processed flag and attach RPC summary to payment_debug
            try {
              const updatedDebugInfo = { ...debugInfo, stock_processed: true, stock_processed_at: new Date().toISOString(), stock_rpc_result: rpcJson };
              await fetch(`${supabaseUrl}/rest/v1/venthub_orders?id=eq.${orderId}`, {
                method: 'PATCH',
                headers: {
                  'Authorization': `Bearer ${serviceRoleKey}`,
                  'apikey': serviceRoleKey,
                  'Content-Type': 'application/json',
                  'Prefer': 'return=minimal'
                },
                body: JSON.stringify({ payment_debug: updatedDebugInfo })
              });
            } catch { /* best-effort */ }

            // Optional: trigger low stock alerts after RPC (best-effort, non-blocking)
            try {
              const itemsResp = await fetch(`${supabaseUrl}/rest/v1/venthub_order_items?_order_id=eq.${orderId}&select=product_id,quantity`, {
                headers: {
                  'Authorization': `Bearer ${serviceRoleKey}`,
                  'apikey': serviceRoleKey
                }
              });
              if (itemsResp.ok) {
                const items = await itemsResp.json().catch(() => []);
                for (const it of items) {
                  try {
                    const pResp = await fetch(`${supabaseUrl}/rest/v1/products?id=eq.${encodeURIComponent(it.product_id)}&select=id,name,stock_qty,low_stock_threshold`, {
                      headers: {
                        'Authorization': `Bearer ${serviceRoleKey}`,
                        'apikey': serviceRoleKey
                      }
                    });
                    if (pResp.ok) {
                      const arr = await pResp.json().catch(() => []);
                      const pr = Array.isArray(arr) ? arr[0] : null;
                      if (pr && Number(pr.stock_qty) <= Number(pr.low_stock_threshold ?? 5)) {
                        await fetch(`${supabaseUrl}/functions/v1/stock-alert`, {
                          method: 'POST',
                          headers: {
                            'Authorization': `Bearer ${serviceRoleKey}`,
                            'Content-Type': 'application/json'
                          },
                          body: JSON.stringify({ _productId: it.product_id })
                        }).catch(() => {});
                      }
                    }
                  } catch { /* ignore */ }
                }
              }
            } catch { /* ignore */ }
          } else {
            const errTxt = await rpcResp.text().catch(() => '');
            console.warn('process_order_stock_reduction failed', rpcResp.status, errTxt);
          }
        }
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e ?? '')
        console.warn('Stock reduction RPC error:', msg);
      }
      
      // After a successful payment, clear ALL server carts for this user (defensive against duplicates)
      try {
        const su = Deno.env.get('SUPABASE_URL') || ''
        const sk = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
        if (su && sk) {
          // Fetch order row to get user_id
          let _u_id: string | null = null
          if (orderId) {
            const oResp = await fetch(`${su}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(orderId)}&select=user_id`, {
              headers: { Authorization: `Bearer ${sk}`, apikey: sk }
            })
            const arr = await oResp.json().catch(()=>[])
            const row = Array.isArray(arr) ? arr[0] : null
            uid = row?.user_id || null
          } else if (result?.conversationId || conversationId) {
            const oResp = await fetch(`${su}/rest/v1/venthub_orders?conversation_id=eq.${encodeURIComponent(result?.conversationId || conversationId!)}&select=user_id`, {
              headers: { Authorization: `Bearer ${sk}`, apikey: sk }
            })
            const arr = await oResp.json().catch(()=>[])
            const row = Array.isArray(arr) ? arr[0] : null
            uid = row?.user_id || null
          }
          if (uid) {
            // Look up ALL shopping carts for the user and clear their items
            const cResp = await fetch(`${su}/rest/v1/shopping_carts?user_id=eq.${encodeURIComponent(uid)}&select=id`, {
              headers: { Authorization: `Bearer ${sk}`, apikey: sk }
            })
      const carts = await cResp.json().catch(()=>[])
      const cartIds: string[] = Array.isArray(carts)
        ? (carts as Array<{ id?: string }>).map((c) => c?.id).filter((v): v is string => Boolean(v))
        : []
            for (const cid of cartIds) {
              await fetch(`${su}/rest/v1/cart_items?cart_id=eq.${encodeURIComponent(cid)}`, {
                method: 'DELETE',
                headers: { Authorization: `Bearer ${sk}`, apikey: sk, Prefer: 'return=minimal' }
              }).catch(()=>{})
            }
          }
        }
      } catch { /* best-effort */ }
    } else if (result && result.paymentStatus && String(result.paymentStatus).toUpperCase() !== 'SUCCESS') {
      const r = await patchStatus('failed');
      updateOk = !!(r && r.ok);
    }

    const responseBody = {
      status: paid ? "success" : (result ? "failure" : "pending"),
      iyzico: result,
      updated: updateOk,
    };

    // İstek JSON bekliyorsa JSON dön, değilse HTML ile yönlendir
    if (wantsJson) {
      return new Response(JSON.stringify(responseBody), { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
    }

    // Her durumda frontende yönlendiren HTML dön (IyziCo bazı durumlarda 302'yi takip etmiyor olabilir)
    try {
      const url = new URL(req.url);
      const successUrl = url.searchParams.get('successUrl');
      let finalSuccess = successUrl;
      if (!finalSuccess) {
        const base = (Deno.env.get('PUBLIC_SITE_URL') || Deno.env.get('FRONTEND_URL') || Deno.env.get('SITE_URL') || '').trim();
        if (base) {
          try { finalSuccess = new URL(base).origin + '/payment-success'; } catch { finalSuccess = base.replace(/\/$/, '') + '/payment-success'; }
        }
      }
      if (finalSuccess) {
        const target = new URL(finalSuccess);
        if (orderId) target.searchParams.set('orderId', orderId);
        if (conversationId) target.searchParams.set('conversationId', conversationId);
        target.searchParams.set('status', paid ? 'success' : 'failure');
        const t = target.toString();
        const html = `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=${t}"><title>Redirecting...</title></head><body><a href=${JSON.stringify(t)}>Devam etmek için tıklayın</a><script>try{window.top.location.replace(${JSON.stringify(t)});}catch(e){try{window.parent.location.replace(${JSON.stringify(t)});}catch(e2){location.href=${JSON.stringify(t)}}};</script></body></html>`;
        return new Response(html, { status: 200, headers: { ...corsHeaders, 'Content-Type': 'text/html' } });
      }
    } catch {}

    // Yine de base yoksa düz metin yerine bilgilendirici HTML döndür (OK kaldırıldı)
    const infoHtml = `<!doctype html><html><head><meta charset="utf-8"><title>Ödeme Sonucu</title></head><body style="font-family:system-ui,Arial,sans-serif;padding:16px;"><h3>Ödeme sonucu alındı</h3><p>Bu pencereyi kapatabilirsiniz. Sonuç sayfasına yönlendirme yapılamadı.</p></body></html>`;
    return new Response(infoHtml, { status: 200, headers: { ...corsHeaders, "Content-Type": "text/html" } });
  } catch (error: unknown) {
    console.error("iyzico-callback error:", error);
    // Hata olsa bile JSON bekleyen isteklere 'pending' JSON dön, aksi halde frontend'e 'pending' ile yönlendir
    const accept = (req.headers.get('accept') || '').toLowerCase()
    const wantsJson = accept.includes('application/json') || !!req.headers.get('x-client-info')
    if (wantsJson) {
      return new Response(JSON.stringify({ status: 'pending', error: String(error?.message || error) }), { status: 200, headers: { "Access-Control-Allow-Origin": "*", "Content-Type": "application/json" } });
    }
    try {
      const url = new URL(req.url);
      const orderId = url.searchParams.get('orderId') || undefined;
      const conversationId = url.searchParams.get('conversationId') || undefined;
      let finalSuccess = url.searchParams.get('successUrl');
      if (!finalSuccess) {
        const base = (Deno.env.get('PUBLIC_SITE_URL') || Deno.env.get('FRONTEND_URL') || Deno.env.get('SITE_URL') || '').trim();
        if (base) {
          try { finalSuccess = new URL(base).origin + '/payment-success'; } catch { finalSuccess = base.replace(/\/$/, '') + '/payment-success'; }
        }
      }
      if (finalSuccess) {
        const target = new URL(finalSuccess);
        if (orderId) target.searchParams.set('orderId', orderId);
        if (conversationId) target.searchParams.set('conversationId', conversationId);
        target.searchParams.set('status', 'failure');
        const t = target.toString();
        const html = `<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=${t}"><title>Redirecting...</title></head><body><a href=${JSON.stringify(t)}>Devam etmek için tıklayın</a><script>try{window.top.location.replace(${JSON.stringify(t)});}catch(e){try{window.parent.location.replace(${JSON.stringify(t)});}catch(e2){location.href=${JSON.stringify(t)}}};</script></body></html>`;
        return new Response(html, { status: 200, headers: { ...corsHeaders, 'Content-Type': 'text/html' } });
      }
    } catch {}
    // Yine olmazsa bilgilendirici HTML döndür (OK kaldırıldı)
    const infoHtml2 = `<!doctype html><html><head><meta charset="utf-8"><title>Ödeme Sonucu</title></head><body style="font-family:system-ui,Arial,sans-serif;padding:16px;"><h3>Ödeme sonucu alındı</h3><p>Bu pencereyi kapatabilirsiniz. Sonuç sayfasına yönlendirme yapılamadı.</p></body></html>`;
    return new Response(infoHtml2, { status: 200, headers: { ...corsHeaders, "Content-Type": "text/html" } });
  }
});

import Iyzipay from "npm:iyzipay";
/* eslint-disable no-console */

/**
 * @file Supabase Edge Function - Iyzico Payment
 * IDE help: Declare Deno for environments without Deno extension
 */
declare const Deno: {
    serve: (handler: (req: Request) => Promise<Response> | Response) => void;
    env: {
        get: (key: string) => string | undefined;
    };
};

Deno.serve(async (req: Request) => {
    const origin = req.headers.get('origin') || '';
    const allowed = (Deno.env.get('ALLOWED_ORIGINS') || '').split(',').map(s => s.trim()).filter(Boolean);
    const okOrigin = allowed.length === 0 || (origin && allowed.includes(origin));
    const requestId = (typeof crypto?.randomUUID === 'function') ? crypto.randomUUID() : String(Date.now());
    const corsHeaders = {
        'Access-Control-Allow-Origin': okOrigin ? (origin || '*') : 'null',
        'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-debug',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Max-Age': '86400',
        'X-Request-Id': requestId,
    } as Record<string, string>;

    if (req.method === 'OPTIONS') {
        return new Response(null, { status: 200, headers: corsHeaders });
    }

    if (!okOrigin && req.method !== 'OPTIONS') {
        return new Response(JSON.stringify({ error: 'forbidden_origin' }), { status: 403, headers: { ...corsHeaders, 'Content-Type': 'application/json', 'X-Request-Id': requestId } });
    }
    if (req.method !== 'POST') {
        return new Response(JSON.stringify({ error: 'Method not allowed' }), {
            status: 405,
            headers: { ...corsHeaders, 'Content-Type': 'application/json', 'X-Request-Id': requestId }
        });
    }
    // Content-Type & size checks
    const ct = (req.headers.get('content-type') || '').toLowerCase();
    if (!ct.includes('application/json')) {
        return new Response(JSON.stringify({ error: 'unsupported_media_type' }), { status: 415, headers: { ...corsHeaders, 'Content-Type': 'application/json', 'X-Request-Id': requestId } });
    }
    const max = parseInt(Deno.env.get('MAX_BODY_KB') || '200', 10) * 1024;
    const cl = parseInt(req.headers.get('content-length') || '0', 10) || 0;
    if (cl > max) {
        return new Response(JSON.stringify({ error: 'payload_too_large' }), { status: 413, headers: { ...corsHeaders, 'Content-Type': 'application/json', 'X-Request-Id': requestId } });
    }

    let debugEnabled = false;
    try {
        const url = new URL(req.url);
        debugEnabled = ((Deno.env.get('IYZICO_DEBUG') || '').toLowerCase() === 'true')
            || (url.searchParams.get('debug') === '1')
            || ((req.headers.get('x-debug') || '') === '1');

        // Per-IP rate limiting
        try {
            const supabaseUrl = Deno.env.get('SUPABASE_URL') || ''
            const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
            if (supabaseUrl && serviceRoleKey) {
                const forwarded = req.headers.get('x-forwarded-for') || ''
                const ip = req.headers.get('x-real-ip') || req.headers.get('cf-connecting-ip') || (forwarded.split(',')[0]?.trim() || '') || 'unknown'
                const key = `iyzico:${ip}`
                const { checkRateLimit, rateLimitHeaders } = await import('../_shared/rate_limit.ts')
                const { result, limit, windowSec } = await checkRateLimit(key, supabaseUrl, serviceRoleKey, { limit: Number(Deno.env.get('PAYMENT_RATE_LIMIT_PER_MINUTE') || 30), windowSec: Number(Deno.env.get('PAYMENT_RATE_LIMIT_WINDOW_SEC') || 60) })
                if (!result.allowed) {
                    const rl = rateLimitHeaders(Number(Deno.env.get('PAYMENT_RATE_LIMIT_PER_MINUTE') || 30), result.remaining, result.resetAt)
                    return new Response(JSON.stringify({ error: { code: 'RATE_LIMITED', message: 'Çok fazla istek' } }), { status: 429, headers: { ...corsHeaders, 'Content-Type': 'application/json', ...rl } })
                }
            }
        } catch (e) {
            if (debugEnabled) console.warn('rate_limit skipped:', e)
        }

        const mask = (s?: string) => typeof s === 'string' ? s.replace(/.(?=.{2})/g, '*') : s;
        type BuyerMin = { email?: string; gsmNumber?: string; registrationAddress?: string; ip?: string }
        type AddressMin = { address?: string }
        type PaymentMin = { buyer?: BuyerMin; shippingAddress?: AddressMin; billingAddress?: AddressMin;[k: string]: unknown }
        const sanitize = (obj: PaymentMin) => ({
            ...obj,
            buyer: obj?.buyer ? { ...obj.buyer, email: mask(obj.buyer.email), gsmNumber: mask(obj.buyer.gsmNumber), registrationAddress: '***', ip: '***' } : undefined,
            shippingAddress: obj?.shippingAddress ? { ...obj.shippingAddress, address: '***' } : undefined,
            billingAddress: obj?.billingAddress ? { ...obj.billingAddress, address: '***' } : undefined,
        });
        if (debugEnabled) console.warn('İyzico Payment Request Started');

        // Parse request body
        const requestData = await req.json();
        const amount = requestData?.amount
        const cartItems = requestData?.cartItems
        const user_id = requestData?.user_id
        const invoiceInfo = requestData?.invoiceInfo
        const invoiceType = requestData?.invoiceType
        const legalConsents = requestData?.legalConsents
        const shippingMethod = requestData?.shippingMethod
        // Coalesce customer/shipping/billing from alternative keys and apply fallbacks
        let ci = requestData?.customerInfo || requestData?.customer || {}
        let shipAddr = requestData?.shippingAddress || requestData?.shipping || requestData?.shipping_address || null
        const billAddr = requestData?.billingAddress || requestData?.billing || requestData?.billing_address || null
        if (!shipAddr && billAddr) shipAddr = billAddr
        if (!ci?.name || String(ci.name).trim().length === 0) {
            const emailStr = String(ci?.email || '')
            const prefix = emailStr.includes('@') ? emailStr.split('@')[0] : 'Musteri'
            ci = { ...(ci || {}), name: prefix }
        }

        // Validate required fields (relaxed): amount/cartItems optional; we derive authoritative items/total below
        if (!(ci?.email) || !(shipAddr?.fullAddress)) {
            const missing = [!ci?.email ? 'email' : null, !shipAddr?.fullAddress ? 'shipping.fullAddress' : null].filter(Boolean)
            return new Response(JSON.stringify({
                error: { code: 'VALIDATION_ERROR', message: 'Eksik alanlar', details: missing }
            }), {
                status: 400,
                headers: { ...corsHeaders, 'Content-Type': 'application/json', 'X-Request-Id': requestId }
            });
        }

        // Environment variables
        const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
        const supabaseUrl = Deno.env.get('SUPABASE_URL');

        if (!serviceRoleKey || !supabaseUrl) {
            return new Response(JSON.stringify({
                error: { code: 'CONFIG_ERROR', message: 'Sunucu yapılandırma hatası' }
            }), {
                status: 500,
                headers: { ...corsHeaders, 'Content-Type': 'application/json', 'X-Request-Id': requestId }
            });
        }

        // Authoritative server-side validation (prices + stock)
        let authoritativeItems: Array<{ product_id: string; quantity: number; unit_price: number; price_list_id: string | null }> = []
        let authoritativeTotalNum: number = typeof amount === 'number' ? Number(amount) : 0
        try {
            const vHeaders = {
                'Authorization': `Bearer ${serviceRoleKey as string}`,
                'apikey': serviceRoleKey as string,
                'Content-Type': 'application/json'
            } as Record<string, string>;
            const vResp = await fetch(`${supabaseUrl}/functions/v1/order-validate`, {
                method: 'POST',
                headers: vHeaders,
                body: JSON.stringify({ user_id })
            });
            if (vResp.ok) {
                interface StockIssue { product_id: string; required: number; available: number }
                interface ValidationResponse {
                    stock_issues?: StockIssue[];
                    mismatches?: unknown[];
                    items?: { product_id: string; quantity: number; unit_price: number; price_list_id: string | null }[];
                    totals?: { subtotal: number };
                }
                const validation = await vResp.json().catch(() => ({})) as ValidationResponse;
                const stockIssues = Array.isArray(validation?.stock_issues) ? validation.stock_issues : [];
                const _mismatches = Array.isArray(validation?.mismatches) ? validation.mismatches : [];
                // Eski davranış: 409 döndürüp akışı durdurmak. Yeni davranış: sunucu otoritesini uygula ve devam et.
                if ((stockIssues && stockIssues.length > 0)) {
                    // Stok problemi varsa yine durdur (kullanıcı müdahalesi gerekir)
                    return new Response(JSON.stringify({ error: { code: 'VALIDATION_STOCK', message: 'Stock issue', stock_issues: stockIssues } }), { status: 409, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
                }
                // Fiyat uyuşmazlığında: authoritativeItems ve subtotal ile devam et (ödeme bloklanmasın)
                authoritativeItems = Array.isArray(validation?.items) ? (validation.items || []) : []
                if (validation?.totals?.subtotal != null) {
                    authoritativeTotalNum = Number(validation.totals.subtotal)
                }
            }
        } catch {
            // fallback to client-requested cartItems
        }
        if (authoritativeItems.length === 0 && Array.isArray(cartItems)) {
            authoritativeItems = (cartItems as Array<{ product_id: string; quantity: number; price?: number }>)
                .map((ci) => ({ product_id: ci.product_id, quantity: ci.quantity, unit_price: Number(ci.price ?? 0), price_list_id: null }))
            authoritativeTotalNum = authoritativeItems.reduce((s, it) => s + Number(it.unit_price) * Number(it.quantity), 0)
        }

        // İyzico credentials (Environment)
        const iyzicoApiKey = Deno.env.get('IYZICO_API_KEY');
        const iyzicoSecretKey = Deno.env.get('IYZICO_SECRET_KEY');
        const iyzicoBaseUrl = Deno.env.get('IYZICO_BASE_URL') || 'https://sandbox-api.iyzipay.com';

        if (!iyzicoApiKey || !iyzicoSecretKey) {
            return new Response(JSON.stringify({
                error: { code: 'CONFIG_ERROR', message: 'IYZICO_API_KEY / IYZICO_SECRET_KEY eksik' }
            }), {
                status: 500,
                headers: { ...corsHeaders, 'Content-Type': 'application/json', 'X-Request-Id': requestId }
            });
        }

        // Maskeli anahtar logu (güvenli): ilk 6 + … + son 4
        const maskKey = (k?: string | null) => {
            if (!k) return '(missing)';
            const s = String(k);
            if (s.length <= 10) return s;
            return s.slice(0, 6) + '…' + s.slice(-4);
        };
        if (debugEnabled) console.warn('Iyzico keys (masked):', maskKey(iyzicoApiKey), maskKey(iyzicoSecretKey));

        // Generate unique identifiers
        const orderId = `VH-${Date.now()}-${Math.random().toString(36).substr(2, 6)}`;
        const conversationId = `CONV-${Date.now()}`;

        // Frontend origin for redirect after callback (if available)
        let clientOrigin = req.headers.get('origin') || '';
        if (!clientOrigin) {
            const ref = req.headers.get('referer') || '';
            try { clientOrigin = ref ? new URL(ref).origin : ''; } catch { clientOrigin = ''; }
        }
        if (!clientOrigin) {
            const envOrigin = (Deno.env.get('PUBLIC_SITE_URL') || Deno.env.get('FRONTEND_URL') || Deno.env.get('SITE_URL') || '').trim();
            if (envOrigin) {
                try { clientOrigin = new URL(envOrigin).origin; } catch { clientOrigin = envOrigin.replace(/\/$/, ''); }
            }
        }

        // Resolve client IP from headers
        const forwarded = req.headers.get('x-forwarded-for') || '';
        const realIp = req.headers.get('x-real-ip') || req.headers.get('cf-connecting-ip') || (forwarded.split(',')[0]?.trim() || '');

        if (debugEnabled) console.warn('Order ID:', orderId);

        // Create order in database
        // Not: venthub_orders.id NOT NULL ise, burada UUID oluşturup gönderiyoruz.
        const dbGeneratedId = typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
        const orderData = {
            _id: dbGeneratedId,
            user_id: user_id || null,
            conversation_id: conversationId,
            // order_number kolonu şemada yoksa göndermiyoruz; gerekirse ileride eklenir.
            total_amount: Number(authoritativeTotalNum.toFixed(2)),
            subtotal_snapshot: Number(authoritativeTotalNum.toFixed(2)),
            shipping_address: shipAddr,
            billing_address: billAddr || shipAddr,
            customer_email: ci.email,
            customer_name: ci.name,
            customer_phone: ci.phone || null,
            payment_method: 'iyzico',
            status: 'pending',
            invoice_type: invoiceType || null,
            invoice_info: invoiceInfo || null,
            legal_consents: legalConsents || null,
            shipping_method: (typeof shippingMethod === 'string' && shippingMethod) ? shippingMethod : 'standard',
            coupon_code: (requestData?.couponCode && typeof requestData.couponCode === 'string') ? requestData.couponCode : null,
            coupon_discount: 0
        };

        // Try creating order; if schema drift (shipping_method column missing), retry without it
        let orderResponse = await fetch(`${supabaseUrl}/rest/v1/venthub_orders`, {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${serviceRoleKey as string}`,
                'apikey': serviceRoleKey as string,
                'Content-Type': 'application/json',
                'Prefer': 'return=representation'
            },
            body: JSON.stringify(orderData)
        });

        if (!orderResponse.ok) {
            const errorText = await orderResponse.text();
            // Fallback: remove shipping_method if column doesn't exist yet
            const mayRetry = /shipping_method/i.test(errorText) && /does not exist|column/i.test(errorText)
            if (mayRetry) {
                const { shipping_method: _shipping_method, ...withoutShipMethod } = orderData as Record<string, unknown>
                orderResponse = await fetch(`${supabaseUrl}/rest/v1/venthub_orders`, {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${serviceRoleKey}`,
                        'apikey': serviceRoleKey,
                        'Content-Type': 'application/json',
                        'Prefer': 'return=representation'
                    },
                    body: JSON.stringify(withoutShipMethod)
                });
            } else {
                console.error('Order creation failed:', errorText);
            }
        }

        if (!orderResponse.ok) {
            try {
                const { slackNotify } = await import('../_shared/notify.ts')
                await slackNotify('DB error while creating order', [
                    { title: 'Request-Id', value: requestId, short: true },
                    { title: 'Status', value: String(orderResponse.status), short: true },
                ])
            } catch { }
            return new Response(JSON.stringify({
                error: { code: 'DATABASE_ERROR', message: 'Sipariş oluşturulamadı' }
            }), {
                status: 500,
                headers: { ...corsHeaders, 'Content-Type': 'application/json' }
            });
        }

        const createdOrders = await orderResponse.json().catch(() => null);
        const dbOrderId = (Array.isArray(createdOrders) && createdOrders[0]?.id) ? createdOrders[0]._id: dbGeneratedId;

        if (debugEnabled) console.warn('✅ Order created successfully with _id:', dbOrderId);


        // Create order items (_order_id olarak veritabanındaki gerçek id kullanılır) using authoritative items
        // Fetch product metadata for snapshots
        const ids = authoritativeItems.map((it) => it.product_id)
        const uniqIds = Array.from(new Set(ids))
        let prodMap = new Map<string, { _id: string; name?: string; sku?: string; image_url?: string | null }>()
        try {
            if (uniqIds.length > 0) {
                const pRes = await fetch(`${supabaseUrl}/rest/v1/products?select=id,name,sku,image_url&id=in.(${uniqIds.map(encodeURIComponent).join(',')})`, {
                    headers: {
                        'Authorization': `Bearer ${serviceRoleKey}`,
                        'apikey': serviceRoleKey,
                        'Content-Type': 'application/json'
                    }
                })
                if (pRes.ok) {
                    const rows = await pRes.json().catch(() => [])
                    if (Array.isArray(rows)) {
                        prodMap = new Map((rows as Array<{ _id: string; name?: string; sku?: string; image_url?: string | null }>).map((p) => [p.id, p]))
                    }
                }
            }
        } catch { }

        // Fallback name/image maps from client cart (in case product metadata is missing)
        const nameMap = new Map<string, string>()
        const imageMap = new Map<string, string | null>()
        try {
            if (Array.isArray(cartItems)) {
                for (const ci of cartItems as Array<{ product_id: string; product_name?: string; product_image_url?: string | null }>) {
                    if (ci?.product_id) {
                        if (ci.product_name) nameMap.set(String(ci.product_id), String(ci.product_name))
                        if (ci.product_image_url !== undefined) imageMap.set(String(ci.product_id), ci.product_image_url as string | null)
                    }
                }
            }
        } catch { }

        // Şema uyumlu kolonlar: _order_id, product_id, product_name, unit_price, quantity, total_price,
        // opsiyonel: price_at_time, product_image_url
        const orderItems = authoritativeItems.map((raw) => {
            const _productId = raw.product_id
            const unitPrice = Number(raw.unit_price)
            const qty = Math.max(1, Number(raw.quantity ?? 1))
            const safeUnit = Number.isFinite(unitPrice) ? unitPrice : 0
            const p = _productId ? (prodMap.get(_productId) as any || {}) : {};
            const fid = String(_productId || '')
            const fallbackName = (p.name) || nameMap.get(fid) || 'Ürün';
            const fallbackImage = (p.image_url) || imageMap.get(fid) || null;
            return {
                _order_id: dbOrderId,
                product_id: _productId,
                product_name: fallbackName,
                unit_price: safeUnit,
                quantity: qty,
                total_price: safeUnit * qty,
                price_at_time: safeUnit,
                product_image_url: fallbackImage,
            }
        });

        // Insert order items ve sonucu kontrol et; başarısızsa işlemi durdur
        const itemsResp = await fetch(`${supabaseUrl}/rest/v1/venthub_order_items`, {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${serviceRoleKey}`,
                'apikey': serviceRoleKey,
                'Content-Type': 'application/json',
                'Prefer': 'return=representation'
            },
            body: JSON.stringify(orderItems)
        });
        if (!itemsResp.ok) {
            const errTxt = await itemsResp.text().catch(() => '')
            console.error('Order items insert failed:', itemsResp.status, errTxt)
            return new Response(JSON.stringify({ error: { code: 'DATABASE_ERROR', message: 'Sipariş kalemleri eklenemedi' } }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
        }

        // İyzico checkout form initialize request
        // Fiyat tutarlılığı: price == basketItems toplamı olmalı, paidPrice >= price olabilir.
        const to2 = (n: number) => Number(Number(n).toFixed(2))
        const toCents = (n: number) => Math.round(Number(n) * 100)
        const basketItems = authoritativeItems.map((item) => ({
            _id: item.product_id,
            name: (typeof prodMap.get === 'function' ? (prodMap.get(item.product_id)?.name) : undefined) || 'Ürün',
            category1: 'HVAC',
            category2: 'Products',
            itemType: 'PHYSICAL',
            price: to2(Number(item.unit_price) * Number(item.quantity)).toFixed(2)
        }));
        // Toplamı kuruş bazında hesapla ve her iki alana da aynı değeri yaz
        const subtotalCents = authoritativeItems.reduce((s: number, it) => s + toCents(Number(it.unit_price)) * Number(it.quantity), 0)
        const normalizedTotal = subtotalCents / 100
        const itemsTotal = normalizedTotal
        const paidPriceNumber = normalizedTotal

        const callbackBase = Deno.env.get('IYZICO_CALLBACK_URL') || (() => {
            const su = Deno.env.get('SUPABASE_URL') || ''
            try {
                const host = new URL(su).host // tnofewwkwlyjsqgwjjga.supabase.co
                const projectRef = host.split('.')[0]
                return `https://${projectRef}.functions.supabase.co/iyzico-callback`
            } catch {
                return ''
            }
        })();
        if (!callbackBase) {
            return new Response(JSON.stringify({ error: { code: 'CONFIG_ERROR', message: 'Callback URL çözümlenemedi' } }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
        }
        const successUrl = clientOrigin ? `${clientOrigin}/payment-success` : '';
        const callbackUrlWithParams = `${callbackBase}?orderId=${encodeURIComponent(dbOrderId)}&conversationId=${encodeURIComponent(conversationId)}${successUrl ? `&successUrl=${encodeURIComponent(successUrl)}` : ''}`;
        const iyzicoRequest: {
            locale: string; conversationId: string; price: string; paidPrice: string; currency: string;
            basketId: string; paymentGroup: string; paymentChannel: string; callbackUrl: string;
            enabledInstallments: number[];
            buyer: { _id: string; name: string; surname: string; gsmNumber: string; email: string; identityNumber: string; lastLoginDate: string; registrationDate: string; registrationAddress: string; ip: string; city: string; country: string; zipCode: string };
            shippingAddress: { contactName: string; city: string; country: string; address: string; zipCode: string };
            billingAddress: { contactName: string; city: string; country: string; address: string; zipCode: string };
            basketItems: Array<{ _id: string; name: string; category1: string; category2: string; itemType: string; price: string }>;
        } = {
            locale: 'tr',
            conversationId: conversationId,
            price: itemsTotal.toFixed(2),
            paidPrice: paidPriceNumber.toFixed(2),
            currency: 'TRY',
            basketId: orderId,
            paymentGroup: 'PRODUCT',
            paymentChannel: 'WEB',
            callbackUrl: callbackUrlWithParams,
            enabledInstallments: [1, 2, 3, 6, 9, 12],
            buyer: {
                _id: user_id || 'guest_' + Date.now(),
                name: (ci.name || '').split(' ')[0] || 'Ad',
                surname: (ci.name || '').split(' ').slice(1).join(' ') || 'Soyad',
                gsmNumber: (() => { const raw = ci.phone || '+905555555555'; const digits = raw.replace(/\s+/g, ''); return digits.startsWith('+') ? digits : ('+' + digits.replace(/[^0-9]/g, '')); })(),
                email: ci.email,
                identityNumber: '11111111110',
                lastLoginDate: new Date().toISOString().split('T')[0] + ' 12:00:00',
                registrationDate: new Date().toISOString().split('T')[0] + ' 12:00:00',
                registrationAddress: shipAddr.fullAddress,
                ip: realIp || '85.34.78.112',
                city: shipAddr.city,
                country: 'Turkey',
                zipCode: shipAddr.postalCode
            },
            shippingAddress: {
                contactName: ci.name,
                city: shipAddr.city,
                country: 'Turkey',
                address: shipAddr.fullAddress,
                zipCode: shipAddr.postalCode
            },
            billingAddress: {
                contactName: ci.name,
                city: (billAddr || shipAddr).city,
                country: 'Turkey',
                address: (billAddr || shipAddr).fullAddress,
                zipCode: (billAddr || shipAddr).postalCode
            },
            basketItems
        };

        if (debugEnabled) console.warn('İyzico Request:', JSON.stringify(sanitize(iyzicoRequest), null, 2));

        // İyzipay Node SDK ile isteği yap
        type IyziStatic = { PAYMENT_CHANNEL?: { WEB: string }, BASKET_ITEM_TYPE?: { PHYSICAL: string } }
        const IYZI = Iyzipay as unknown as IyziStatic
        type IyziSdk = { checkoutFormInitialize: { create: (req: Record<string, unknown>, cb: (err: unknown, res: { status?: string; token?: string; paymentPageUrl?: string; checkoutFormContent?: string; errorMessage?: string }) => void) => void } }
        const IyziCtor = Iyzipay as unknown as { new(args: { apiKey: string; secretKey: string; uri: string }): IyziSdk }
        const sdk = new IyziCtor({ apiKey: iyzicoApiKey, secretKey: iyzicoSecretKey, uri: iyzicoBaseUrl });

        const sdkRequest: Record<string, unknown> = {
            locale: iyzicoRequest.locale,
            conversationId: iyzicoRequest.conversationId,
            price: iyzicoRequest.price,
            paidPrice: iyzicoRequest.paidPrice,
            currency: iyzicoRequest.currency,
            basketId: iyzicoRequest.basketId,
            paymentGroup: iyzicoRequest.paymentGroup,
            paymentChannel: IYZI.PAYMENT_CHANNEL?.WEB ?? 'WEB',
            callbackUrl: iyzicoRequest.callbackUrl,
            enabledInstallments: iyzicoRequest.enabledInstallments,
            buyer: iyzicoRequest.buyer,
            shippingAddress: iyzicoRequest.shippingAddress,
            billingAddress: iyzicoRequest.billingAddress,
            basketItems: iyzicoRequest.basketItems.map((it) => ({
                _id: it.id,
                name: it.name,
                category1: it.category1,
                category2: it.category2,
                itemType: IYZI.BASKET_ITEM_TYPE?.PHYSICAL ?? 'PHYSICAL',
                price: it.price,
            })),
        };

        const iyzicoResult = await new Promise<{ status?: string; token?: string; paymentPageUrl?: string; checkoutFormContent?: string; errorMessage?: string }>((resolve, reject) => {
            sdk.checkoutFormInitialize.create(sdkRequest, (err: unknown, res: { status?: string; token?: string; paymentPageUrl?: string; checkoutFormContent?: string; errorMessage?: string }) => {
                if (err) return reject(err);
                resolve(res);
            });
        });

        if (debugEnabled) console.warn('İyzico Result:', { status: iyzicoResult?.status, hasToken: !!iyzicoResult?.token, hasPaymentPageUrl: !!iyzicoResult?.paymentPageUrl });
        if (iyzicoResult && iyzicoResult.status === 'success' && (iyzicoResult.checkoutFormContent || iyzicoResult.paymentPageUrl || iyzicoResult.token)) {
            if (debugEnabled) console.warn('✅ İyzico checkout form created successfully');

            // Minimal token saklama: reconcile için yeterli.
            try {
                if (iyzicoResult.token) {
                    await fetch(`${supabaseUrl}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(dbOrderId)}`, {
                        method: 'PATCH',
                        headers: {
                            'Authorization': `Bearer ${serviceRoleKey}`,
                            'apikey': serviceRoleKey,
                            'Content-Type': 'application/json',
                            'Prefer': 'return=minimal'
                        },
                        body: JSON.stringify({ payment_token: iyzicoResult.token })
                    })
                }
            } catch (e) {
                const msg = e instanceof Error ? e.message : String(e ?? '')
                console.warn('payment_data token patch skipped:', msg)
            }

            return new Response(JSON.stringify({
                data: {
                    status: 'success',
                    orderId: dbOrderId,
                    orderNumber: orderId,
                    conversationId: conversationId,
                    checkoutFormContent: iyzicoResult.checkoutFormContent,
                    paymentPageUrl: iyzicoResult.paymentPageUrl,
                    token: iyzicoResult.token,
                    amount: Number(paidPriceNumber.toFixed(2)),
                    currency: 'TRY'
                }
            }), {
                status: 200,
                headers: { ...corsHeaders, 'Content-Type': 'application/json' }
            });
        } else {
            console.error('İyzico checkout form creation failed:', iyzicoResult);
            try {
                const { slackNotify } = await import('../_shared/notify.ts')
                await slackNotify('İyzico checkout form creation failed', [
                    { title: 'Request-Id', value: requestId, short: true },
                    { title: 'Details', value: String(iyzicoResult?.errorMessage || 'unknown'), short: false },
                ])
            } catch { }

            return new Response(JSON.stringify({
                error: {
                    code: 'IYZICO_FORM_ERROR',
                    message: 'İyzico ödeme formu oluşturulamadı',
                    details: iyzicoResult.errorMessage || 'Bilinmeyen hata'
                }
            }), {
                status: 500,
                headers: { ...corsHeaders, 'Content-Type': 'application/json' }
            });
        }

    } catch (error) {
        if (debugEnabled) console.error('Critical Error:', error);
        try {
            const { slackNotify } = await import('../_shared/notify.ts')
            const errMsg = error instanceof Error ? error.message : String(error)
            await slackNotify('iyzico-payment crashed', [
                { title: 'Request-Id', value: requestId, short: true },
                { title: 'Error', value: errMsg, short: false },
            ])
        } catch { }

        return new Response(JSON.stringify({
            error: {
                code: 'INTERNAL_ERROR',
                message: 'Sunucu hatası oluştu',
                details: error instanceof Error ? error.message : String(error)
            }
        }), {
            status: 500,
            headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });
    }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { sentryCaptureException } from "../_shared/sentry.ts"

function renderTemplate(tpl: string, data: Record<string, unknown>): string {
  tpl = tpl.replace(/{{#if\s+(\w+)}}([\s\S]*?){{\/?if}}/g, (_m, key: string, inner: string) => {
    const v = data[key]
    const truthy = !!(typeof v === 'string' ? v : v)
    return truthy ? inner : ''
  })
  tpl = tpl.replace(/{{(\w+)}}/g, (_m, key: string) => {
    const v = data[key]
    return v == null ? '' : String(v)
  })
  return tpl
}

async function loadTemplate(): Promise<string | null> {
  try {
    const url = new URL('./templates/email/order_confirmation.html', import.meta.url)
    return await Deno.readTextFile(url)
  } catch { return null }
}

serve(async (req) => {
  // CORS: origin whitelist (ALLOWED_ORIGINS), yoksa sadece gelen Origin'e vary başlığı ile cevap ver
  const requestOrigin = req.headers.get('origin') || ''
  const allowedOrigins = (Deno.env.get('ALLOWED_ORIGINS') || '').split(',').map(s=>s.trim()).filter(Boolean)
  const originAllowed = allowedOrigins.length === 0 || (requestOrigin && allowedOrigins.includes(requestOrigin))
  const cors = {
    'Access-Control-Allow-Origin': originAllowed ? (requestOrigin || '*') : 'null',
    'Vary': 'Origin',
    'Access-Control-Allow-Headers': req.headers.get('access-control-request-headers') ?? 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': req.headers.get('access-control-request-method') ?? 'POST, OPTIONS',
    'Access-Control-Max-Age': '86400',
  }
  if (!originAllowed && req.method !== 'OPTIONS') {
    return new Response(JSON.stringify({ error: 'forbidden_origin' }), { status: 403, headers: { ...cors, 'Content-Type': 'application/json' } })
  }

  if (req.method === 'OPTIONS') return new Response(null, { status: 200, headers: cors })
  if (req.method !== 'POST') return new Response(JSON.stringify({ error: 'method_not_allowed' }), { status: 405, headers: { ...cors, 'Content-Type': 'application/json' } })

  try {
    const text = await req.text()
    let parsed: Record<string, unknown> = {}
    try { parsed = text ? JSON.parse(text) : {} } catch {}

    // inputs
    const _order_id = ((): string | null => {
      const v = parsed['_order_id']
      if (typeof v === 'string' && v.trim()) return v.trim()
      return null
    })()

    const supabaseUrl = Deno.env.get('SUPABASE_URL') || ''
    const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
    const resendApiKey = Deno.env.get('RESEND_API_KEY') || ''
    const emailFrom = Deno.env.get('EMAIL_FROM') || 'VentHub Test <onboarding@resend.dev>'
    const testMode = (Deno.env.get('EMAIL_TEST_MODE') || '').toLowerCase() === 'true'
    const testTo = Deno.env.get('EMAIL_TEST_TO') || 'delivered@resend.dev'
    const bccList = (Deno.env.get('SHIP_EMAIL_BCC') || '').split(',').map(s=>s.trim()).filter(Boolean)

    const brandName = Deno.env.get('BRAND_NAME') || 'VentHub'
    const brandPrimary = Deno.env.get('BRAND_PRIMARY_COLOR') || '#2563eb'
    const brandLogoUrl = Deno.env.get('BRAND_LOGO_URL') || ''

    if (!supabaseUrl || !serviceKey || !resendApiKey) {
      return new Response(JSON.stringify({ error: 'CONFIG_MISSING' }), { status: 500, headers: { ...cors, 'Content-Type': 'application/json' } })
    }

    if (!_order_id) {
      return new Response(JSON.stringify({ error: 'missing_fields', missing: ['_order_id'] }), { status: 400, headers: { ...cors, 'Content-Type': 'application/json' } })
    }

    // fetch order basics
    let customer_email: string | null = null
    let customer_name: string | null = null
    let order_number: string | null = null
    try {
      const o = await fetch(`${supabaseUrl}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(_order_id)}&select=user_id,customer_email,customer_name,order_number`, {
        headers: { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey }
      })
      if (o.ok) {
        const arr = await o.json().catch(()=>[])
        const row = Array.isArray(arr) ? arr[0] : null
        if (row) {
          order_number = row.order_number || null
          customer_email = row.customer_email || null
          customer_name = row.customer_name || null
          const uid = row.user_id || null
          if ((!customer_email || !customer_name) && uid) {
            const u = await fetch(`${supabaseUrl}/auth/v1/admin/users/${encodeURIComponent(uid)}`, { headers: { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey } })
            if (u.ok) {
              const uj = await u.json().catch(()=>null) as any
              if (uj) {
                customer_email = customer_email || uj.email || null
                const metaName = (uj.user_metadata && (uj.user_metadata.full_name || uj.user_metadata.name)) || null
                customer_name = customer_name || metaName || customer_name
              }
            }
          }
        }
      }
    } catch {}

    // recipients
    const toList: string[] = []
    if (testMode) toList.push(testTo)
    else if (customer_email) toList.push(customer_email)
    let bcc = [...bccList]
    if (toList.length === 0 && bcc.length > 0) { toList.push(bcc[0]); bcc = bcc.slice(1) }

    const prettyOrderNo = order_number ? `#${String(order_number).split('-')[1]}` : `#${_order_id.slice(-8).toUpperCase()}`
    const subject = `${brandName} | Siparişiniz alındı - ${prettyOrderNo}`

    // Load template
    let html = ''
    try {
      const tpl = await loadTemplate()
      if (tpl) html = renderTemplate(tpl, { brand_name: brandName, brand_primary_color: brandPrimary, brand_logo_url: brandLogoUrl, customer_name, order_number: prettyOrderNo })
    } catch {}
    if (!html) {
      html = [
        '<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:0 auto;">',
        `<h2 style=\"color:${brandPrimary}\">${brandName} — Siparişiniz alındı</h2>`,
        `<p>Merhaba <strong>${customer_name || ''}</strong>,</p>`,
        `<p><strong>${prettyOrderNo}</strong> numaralı siparişiniz için ödemeniz başarıyla alındı ve siparişiniz kargoya hazırlanmaya alındı. Hazır olur olmaz kargo ve takip bilgilerini ayrıca ileteceğiz.</p>`,
        `<p>Teşekkürler,<br><strong>${brandName} Ekibi</strong></p>`,
        '</div>'
      ].join('')
    }

    // send
    async function send() {
      return await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${resendApiKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ from: emailFrom, to: toList, bcc: bcc.length > 0 ? bcc : undefined, subject, html, text: `${subject}` })
      })
    }

    let resp = await send()
    if (!resp.ok) {
      const txt = await resp.text().catch(()=> '')
      if (txt.toLowerCase().includes('domain') && txt.toLowerCase().includes('verify')) {
        emailFrom = 'VentHub Test <onboarding@resend.dev>'
        resp = await send()
      }
      if (!resp.ok) return new Response(JSON.stringify({ error: 'send_failed', body: txt }), { status: 500, headers: { ...cors, 'Content-Type': 'application/json' } })
    }
    const result = await resp.json().catch(()=> ({}))

    // Log best-effort
    try {
      await fetch(`${supabaseUrl}/rest/v1/order_email_events`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
        body: JSON.stringify({ _order_id, email_to: toList[0] || '', subject, provider: 'resend', provider_message_id: result?.id || result?.data?.id || null })
      })
    } catch {}

    return new Response(JSON.stringify({ success: true, subject, result }), { status: 200, headers: { ...cors, 'Content-Type': 'application/json' } })
  } catch (e) {
    try { await sentryCaptureException(e as unknown, { fn: 'order-confirmation' }) } catch {}
    const msg = e instanceof Error ? e.message : String(e)
    return new Response(JSON.stringify({ error: 'unexpected', message: msg }), { status: 500, headers: { ...cors, 'Content-Type': 'application/json' } })
  }
})

import { serve } from "https://deno.land/std@0.168.0/http/server.ts"

interface ReturnStatusNotificationRequest {
  _return_id: string
  _order_id?: string
  order_number?: string
  customer_email?: string
  customer_name?: string
  old_status: string
  new_status: string
  reason: string
  description?: string | null
}

serve(async (req) => {
  const corsHeaders = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
    'Access-Control-Allow-Methods': 'POST, OPTIONS',
  }

  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 200, headers: corsHeaders })
  }

  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    })
  }

  try {
    const body = await req.json() as ReturnStatusNotificationRequest

    // Extract and then resolve sensitive fields server-side
    let { 
      _return_id,
      _order_id, 
      order_number,
      old_status,
      new_status,
      reason,
      description
    } = body

    const supabaseUrl = Deno.env.get('SUPABASE_URL') || ''
    const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''

    let customer_email: string | undefined = undefined
    let customer_name: string | undefined = undefined
    let user_id: string | undefined = undefined

    if (!supabaseUrl || !serviceKey) {
      // Fallback to client-provided values only if server config missing
      customer_email = body.customer_email
      customer_name = body.customer_name
    } else {
      try {
        // 1) If _order_id not provided, look up from returns
        if (!_order_id && _return_id) {
          const retRes = await fetch(`${supabaseUrl}/rest/v1/venthub_returns?id=eq.${encodeURIComponent(_return_id)}&select=_order_id,user_id`, {
            headers: { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey }
          })
          if (retRes.ok) {
            const retArr = await retRes.json().catch(() => [])
            const ret = Array.isArray(retArr) ? retArr[0] : null
            if (ret) { _order_id = ret._order_id || _order_id; user_id = ret.user_id || user_id }
          }
        }

        // 2) Load order to get canonical customer info
        if (_order_id) {
          const ordRes = await fetch(`${supabaseUrl}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(_order_id)}&select=order_number,customer_name,customer_email,user_id`, {
            headers: { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey }
          })
          if (ordRes.ok) {
            const ordArr = await ordRes.json().catch(() => [])
            const ord = Array.isArray(ordArr) ? ordArr[0] : null
            if (ord) {
              order_number = ord.order_number || order_number
              customer_email = ord.customer_email || customer_email
              customer_name = ord.customer_name || customer_name
              user_id = ord.user_id || user_id
            }
          }
        }

        // 3) Fallback to Auth Admin API if still missing
        if ((!customer_email || !customer_name) && user_id) {
          const authRes = await fetch(`${supabaseUrl}/auth/v1/admin/users/${encodeURIComponent(user_id)}`, {
            headers: { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey, 'Content-Type': 'application/json' }
          })
          if (authRes.ok) {
            const u = await authRes.json().catch(() => null)
            if (u) {
              customer_email = customer_email || u?.email || undefined
              const meta = (u?.user_metadata || {}) as { full_name?: string; name?: string }
              customer_name = customer_name || meta.full_name || meta.name || undefined
            }
          }
        }
      } catch {
        // ignore and fallback to client-provided
      }

      // Final fallback to client-sent values (if unknown)
      if (!customer_email) customer_email = body.customer_email
      if (!customer_name) customer_name = body.customer_name
    }

    // Validate required fields (after server-side resolution)
    if (!_return_id || !new_status) {
      return new Response(JSON.stringify({ 
        error: 'Missing required fields: _return_id, new_status' 
      }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      })
    }
    if (!customer_email || !customer_name) {
      return new Response(JSON.stringify({ 
        error: 'Customer info unavailable', code: 'CUSTOMER_INFO_MISSING' 
      }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      })
    }

    const prettyOrderNo = order_number ? `#${order_number.split('-')[1]}` : `#${_order_id?.slice(-8).toUpperCase() || 'N/A'}`
    
    // Status labels in Turkish
    const getStatusLabel = (status: string): string => {
      const labels: Record<string, string> = {
        requested: 'Talep Alındı',
        approved: 'Onaylandı', 
        rejected: 'Reddedildi',
        in_transit: 'Kargoda (İade)',
        received: 'İade Teslim Alındı',
        refunded: 'İade Ücreti Ödendi',
        cancelled: 'İptal Edildi'
      }
      return labels[status] || status
    }

    const statusLabel = getStatusLabel(new_status)
    const emailSubject = `İade durumu güncellendi - ${prettyOrderNo}`
    
    // Get status-specific message and next steps
    const getStatusMessage = (status: string): { message: string; nextSteps?: string } => {
      switch (status) {
        case 'approved':
          return {
            message: 'İade talebiniz onaylandı! Ürünü kargoya verebilirsiniz.',
            nextSteps: 'Kargo bilgileri e-posta ile tarafınıza iletilecektir. Ürünü orijinal ambalajında ve tüm aksesuarları ile birlikte gönderiniz.'
          }
        case 'rejected':
          return {
            message: 'İade talebiniz maalesef reddedildi.',
            nextSteps: 'Daha fazla bilgi için müşteri hizmetleri ile iletişime geçebilirsiniz.'
          }
        case 'in_transit':
          return {
            message: 'İade ürününüz kargoda! Teslimatı bekleniyor.',
            nextSteps: 'Ürününüzü aldığımızda kontrol edilecek ve işleminiz devam edecektir.'
          }
        case 'received':
          return {
            message: 'İade ürününüz tarafımıza ulaştı ve kontrol ediliyor.',
            nextSteps: 'Kontrol tamamlandıktan sonra iade ücreti hesabınıza iade edilecektir.'
          }
        case 'refunded':
          return {
            message: '🎉 İade ücretiniz hesabınıza iade edildi!',
            nextSteps: 'İade tutarı 1-3 iş günü içinde hesabınızda görünecektir. Bizi tercih ettiğiniz için teşekkürler.'
          }
        case 'cancelled':
          return {
            message: 'İade işlemi iptal edildi.',
            nextSteps: 'Sorularınız için müşteri hizmetleri ile iletişime geçebilirsiniz.'
          }
        default:
          return { message: `İade durumunuz güncellendi: ${statusLabel}` }
      }
    }

    const { message, nextSteps } = getStatusMessage(new_status)
    
    const emailContent = `
Merhaba ${customer_name},

${prettyOrderNo} numaralı siparişinizin iade durumu güncellendi.

📦 İade Sebepleri: ${reason}
${description ? `📝 Açıklama: ${description}` : ''}

🔄 Yeni Durum: ${statusLabel}

${message}

${nextSteps ? `\n📋 Sonraki Adımlar:\n${nextSteps}` : ''}

İade süreci ile ilgili sorularınız için destek ekibimizle iletişime geçebilirsiniz.

Teşekkürler,
VentHub Ekibi

---
Bu otomatik bir e-postadır. Lütfen yanıtlamayın.
    `.trim()

    const resendApiKey = Deno.env.get('RESEND_API_KEY')
    const emailFrom = Deno.env.get('EMAIL_FROM') || 'VentHub <info@venthub.com>'
    const notifyDebug = Deno.env.get('NOTIFY_DEBUG') === 'true'
    if (!resendApiKey) {
      if (notifyDebug) console.warn('[return-status-notification] Email disabled: missing RESEND_API_KEY')
      return new Response(JSON.stringify({ success: true, disabled: true, channel: 'email' }), { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }

    // Direct email sending
    const response = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${resendApiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        from: emailFrom,
        to: [customer_email],
        subject: emailSubject,
        text: emailContent,
        html: `
          <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
            <h2 style="color: #2563eb;">İade Durumu Güncellendi</h2>
            <p>Merhaba <strong>${customer_name}</strong>,</p>
            <p><strong>${prettyOrderNo}</strong> numaralı siparişinizin iade durumu güncellendi.</p>
            
            <div style="background-color: #f8fafc; padding: 20px; border-radius: 8px; margin: 20px 0;">
              <h3 style="margin-top: 0; color: #374151;">İade Bilgileri</h3>
              <p><strong>📦 İade Sebebi:</strong> ${reason}</p>
              ${description ? `<p><strong>📝 Açıklama:</strong> ${description}</p>` : ''}
              <div style="background-color: #dbeafe; border-left: 4px solid #2563eb; padding: 12px; margin: 12px 0;">
                <p style="margin: 0;"><strong>🔄 Yeni Durum:</strong> <span style="color: #1d4ed8; font-weight: bold;">${statusLabel}</span></p>
              </div>
            </div>
            
            <div style="background-color: #ecfccb; padding: 16px; border-radius: 8px; margin: 20px 0;">
              <p style="margin: 0; color: #365314;"><strong>${message}</strong></p>
            </div>
            
            ${nextSteps ? `
            <div style="background-color: #fef3c7; padding: 16px; border-radius: 8px; margin: 20px 0;">
              <h4 style="margin-top: 0; color: #92400e;">📋 Sonraki Adımlar:</h4>
              <p style="margin-bottom: 0; color: #92400e;">${nextSteps}</p>
            </div>
            ` : ''}
            
            <p>İade süreci ile ilgili sorularınız için destek ekibimizle iletişime geçebilirsiniz.</p>
            <p>Teşekkürler,<br><strong>VentHub Ekibi</strong></p>
            
            <hr style="margin-top: 30px; border: none; border-top: 1px solid #e5e7eb;">
            <p style="color: #6b7280; font-size: 14px;">Bu otomatik bir e-postadır. Lütfen yanıtlamayın.</p>
          </div>
        `,
      }),
    })

    if (!response.ok) {
      const error = await response.text()
      throw new Error(`Email send failed: ${error}`)
    }

    const result = await response.json()

    console.warn(`📧 Return status notification sent to ${customer_email} for return ${_return_id}: ${old_status} → ${new_status}`)

    return new Response(JSON.stringify({ 
      success: true,
      result,
      _return_id,
      customer_email,
      new_status,
      timestamp: new Date().toISOString()
    }), {
      status: 200,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    })

  } catch (error: unknown) {
    console.error('Return status notification error:', error)
    
    const msg = error instanceof Error ? error.message : 'Unknown error'
    return new Response(JSON.stringify({ 
      error: msg,
      success: false 
    }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    })
  }
})

// supabase/functions/returns-webhook/index.ts
// Receives carrier webhook for return shipments. On delivered, marks venthub_returns.status='received'.
// Env: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, RETURNS_WEBHOOK_SECRET (HMAC) or RETURNS_WEBHOOK_TOKEN

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

function json(body: unknown, init: ResponseInit = {}) {
  return new Response(JSON.stringify(body, null, 2), { status: init.status || 200, headers: { 'content-type': 'application/json; charset=utf-8', ...(init.headers||{}) } })
}

async function hmacValid(secret: string, raw: string, signatureHeader: string): Promise<boolean> {
  try {
    const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
    const sigBytes = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(raw))
    const computed = btoa(String.fromCharCode(...new Uint8Array(sigBytes)))
    const given = signatureHeader.trim().replace(/^sha256=/i, '')
    return given === computed
  } catch {
    return false
  }
}

function mapReturnStatus(input?: string): { status?: string; setReceived?: boolean } {
  const s = (input || '').toLowerCase()
  if (!s) return {}
  if (['in_transit','transit','return_in_transit','returning'].includes(s)) return { status: 'in_transit' }
  if (['received','delivered','returned','completed'].includes(s)) return { status: 'received', setReceived: true }
  if (['cancelled','canceled'].includes(s)) return { status: 'cancelled' }
  return { status: s }
}

function normalizePayload(obj: unknown) {
  const rec = (typeof obj === 'object' && obj !== null) ? (obj as Record<string, unknown>) : {}
  const pick = (...keys: string[]) => { for (const k of keys) { if (k in rec) { const v = rec[k]; if (v!=null) return v } } return undefined }
  return {
    _return_id: (pick('_return_id','returnId','rid') || '').toString(),
    _order_id: (pick('_order_id','orderId','id') || '').toString(),
    carrier: (pick('carrier','provider') || '').toString(),
    tracking_number: (pick('tracking_number','trackingNumber','tn') || '').toString(),
    status: (pick('status','state') || '').toString(),
    delivered_at: (pick('delivered_at','deliveredAt','deliveryDate') || '').toString(),
  }
}

async function sha256Base64(input: string): Promise<string> {
  const bytes = new TextEncoder().encode(input)
  const hash = await crypto.subtle.digest('SHA-256', bytes)
  return btoa(String.fromCharCode(...new Uint8Array(hash)))
}

Deno.serve(async (req: Request) => {
  try {
    if (req.method !== 'POST') return json({ error: 'Method not allowed' }, { status: 405 })

    const raw = await req.text()
    let body: unknown = {}
    try { body = JSON.parse(raw) } catch {}

    const secret = Deno.env.get('RETURNS_WEBHOOK_SECRET') || ''
    const token = Deno.env.get('RETURNS_WEBHOOK_TOKEN') || ''
    const sign = req.headers.get('x-signature') || ''
    const tok = req.headers.get('x-webhook-token') || ''
    let ok = false
    if (secret && sign) ok = await hmacValid(secret, raw, sign)
    if (!ok && token && tok && tok === token) ok = true
    if (!ok) return json({ error: 'Unauthorized' }, { status: 401 })

    const SUPABASE_URL = Deno.env.get('SUPABASE_URL')
    const SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
    if (!SUPABASE_URL || !SERVICE_KEY) return json({ error: 'Config missing' }, { status: 500 })

    const supabase = createClient(SUPABASE_URL, SERVICE_KEY)

    const p = normalizePayload(body) as { _return_id?: string; _order_id?: string; carrier?: string; tracking_number?: string; status?: string; delivered_at?: string }

    // Optional dedup
    const eventId = (req.headers.get('x-id') || req.headers.get('x-event-id') || '').trim()
    if (eventId) {
      const { data: exist } = await supabase.from('returns_webhook_events').select('event_id').eq('event_id', eventId).limit(1)
      if (Array.isArray(exist) && exist.length > 0) return json({ ok: true, event_id: eventId, duplicate: true })
    }

    // Resolve _return_id if missing using _order_id + tracking_number if necessary (best effort)
    let returnId = (p._return_id || '').trim()
    if (!returnId && p._order_id) {
      try {
        const { data } = await supabase.from('venthub_returns').select('id').eq('_order_id', p._order_id).order('created_at',{ ascending:false }).limit(1)
        if (Array.isArray(data) && data[0]) returnId = data[0].id
      } catch {}
    }
    if (!returnId) return json({ error: 'Missing _return_id' }, { status: 400 })

    // Fetch current status
    const { data: cur, error: curErr } = await supabase.from('venthub_returns').select('id,status').eq('id', returnId).single()
    if (curErr || !cur) return json({ error: 'Return not found' }, { status: 404 })

    const mapped = mapReturnStatus(p.status)
    const patch: Record<string, unknown> = {}
    if (mapped.status) patch['status'] = mapped.status

    // Only allow progression to received (or mapped status) and never regress silently
    const rank: Record<string, number> = { requested:0, approved:1, rejected:1, in_transit:2, received:3, refunded:4, cancelled:4 }
    const curRank = rank[String(cur.status) as string] ?? 0
    const nextRank = rank[String(patch['status']) as string] ?? curRank
    if (nextRank < curRank) {
      return json({ ok: true, unchanged: true, reason: 'regression_blocked' })
    }

    // Update returns row
    let updated = false
    if (Object.keys(patch).length > 0) {
      const { error: updErr } = await supabase.from('venthub_returns').update(patch).eq('id', returnId)
      if (updErr) return json({ error: updErr.message || 'DB update failed' }, { status: 500 })
      updated = true
    }

    // Audit event
    try {
      const bodyHash = await sha256Base64(raw)
      if (eventId) {
        await supabase.from('returns_webhook_events').insert({
          event_id: eventId,
          _return_id: returnId,
          _order_id: p._order_id || null,
          carrier: p.carrier || null,
          tracking_number: p.tracking_number || null,
          status_raw: p.status || null,
          status_mapped: (patch['status'] as string) || String(cur.status),
          body_hash: bodyHash,
          received_at: new Date().toISOString(),
          processed_at: new Date().toISOString(),
        })
      }
    } catch {}

    // Optional email: send only when we progressed to 'received'
    try {
      const nextStatus = (patch['status'] as string) || String(cur.status)
      if (updated && nextStatus === 'received') {
        // Load full return + order + user for notification payload
        const SUPABASE_URL = Deno.env.get('SUPABASE_URL') || ''
        const SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
        if (SUPABASE_URL && SERVICE_KEY) {
          // 1) Return details (reason, description, _order_id fallback)
          let rOrderId = p._order_id || ''
          const reason = ''
          const description = ''
          try {
            const r = await fetch(`${SUPABASE_URL}/rest/v1/venthub_returns?id=eq.${encodeURIComponent(returnId)}&select=_order_id,reason,description,status`, {
              headers: { Authorization: `Bearer ${SERVICE_KEY}`, apikey: SERVICE_KEY }
            })
            if (r.ok) {
              const arr = await r.json().catch(()=>[])
              const row = Array.isArray(arr) ? arr[0] : null
              if (row) {
                rOrderId = rOrderId || String(row._order_id || '')
                reason = String(row.reason || '')
                description = String(row.description || '')
              }
            }
          } catch {}
          // 2) Order details (order_number, user_id)
          let orderNumber = ''
          let userId = ''
          if (rOrderId) {
            try {
              const o = await fetch(`${SUPABASE_URL}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(rOrderId)}&select=order_number,user_id`, {
                headers: { Authorization: `Bearer ${SERVICE_KEY}`, apikey: SERVICE_KEY }
              })
              if (o.ok) {
                const arr = await o.json().catch(()=>[])
                const row = Array.isArray(arr) ? arr[0] : null
                if (row) {
                  orderNumber = String(row.order_number || '')
                  userId = String(row.user_id || '')
                }
              }
            } catch {}
          }
          // 3) User email/name via Auth Admin API
          let customerEmail = ''
          let customerName = ''
          if (userId) {
            try {
              const u = await fetch(`${SUPABASE_URL}/auth/v1/admin/users/${encodeURIComponent(userId)}`, {
                headers: { Authorization: `Bearer ${SERVICE_KEY}`, apikey: SERVICE_KEY }
              })
              if (u.ok) {
                const ju = await u.json().catch(()=>null) as any
                if (ju) {
                  customerEmail = String(ju.email || '')
                  const meta = (ju.user_metadata || {}) as { full_name?: string; name?: string }
                  customerName = String(meta.full_name || meta.name || '')
                }
              }
            } catch {}
          }
          // 4) Invoke return-status-notification
          if (customerEmail && customerName) {
            try {
              await fetch(`${SUPABASE_URL}/functions/v1/return-status-notification`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${SERVICE_KEY}`, apikey: SERVICE_KEY },
                body: JSON.stringify({
                  _return_id: returnId,
                  _order_id: rOrderId,
                  order_number: orderNumber,
                  customer_email: customerEmail,
                  customer_name: customerName,
                  old_status: String(cur.status || ''),
                  new_status: nextStatus,
                  reason,
                  description
                })
              })
            } catch {}
          }
        }
      }
    } catch {}

    return json({ ok: true, _return_id: returnId, status: (patch['status'] || cur.status) })
  } catch (e) {
    return json({ error: (e as Error).message || 'Unexpected error' }, { status: 500 })
  }
})

import { serve } from "https://deno.land/std@0.168.0/http/server.ts"
import { sentryCaptureException } from "../_shared/sentry.ts"

// Tiny template renderer for {{var}} and {{#if var}} ... {{/if}}
function renderTemplate(tpl: string, data: Record<string, unknown>): string {
  // if-blocks
  tpl = tpl.replace(/{{#if\s+(\w+)}}([\s\S]*?){{\/?if}}/g, (_m, key: string, inner: string) => {
    const v = data[key]
    const truthy = !!(typeof v === 'string' ? v : v)
    return truthy ? inner : ''
  })
  // variables
  tpl = tpl.replace(/{{(\w+)}}/g, (_m, key: string) => {
    const v = data[key]
    return v == null ? '' : String(v)
  })
  return tpl
}

async function loadShippingTemplate(): Promise<string | null> {
  try {
    const url = new URL('./templates/email/shipping.html', import.meta.url)
    return await Deno.readTextFile(url)
  } catch {
    return null
  }
}

interface ShippingNotificationRequest {
  _order_id: string
  customer_email: string
  customer_name: string
  order_number?: string
  carrier: string
  tracking_number: string
  tracking_url?: string | null
}

serve(async (req) => {
  const requestOrigin = req.headers.get('origin') || ''
  const requestHeaders = req.headers.get('access-control-request-headers') ?? 'authorization, x-client-info, apikey, content-type'
  const requestMethod = req.headers.get('access-control-request-method') ?? 'POST, OPTIONS'
  const allowedOrigins = (Deno.env.get('ALLOWED_ORIGINS') || '').split(',').map(s=>s.trim()).filter(Boolean)
  const originAllowed = allowedOrigins.length === 0 || (requestOrigin && allowedOrigins.includes(requestOrigin))
  const corsHeaders = {
    'Access-Control-Allow-Origin': originAllowed ? (requestOrigin || '*') : 'null',
    'Vary': 'Origin',
    'Access-Control-Allow-Headers': requestHeaders,
    'Access-Control-Allow-Methods': requestMethod,
    'Access-Control-Max-Age': '86400',
  }
  if (!originAllowed && req.method !== 'OPTIONS') {
    return new Response(JSON.stringify({ error: 'forbidden_origin' }), { status: 403, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
  }

  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 200, headers: corsHeaders })
  }

  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    })
  }

  try {
    // Parse body robustly and support camelCase as well
    const text = await req.text()
    let parsed: Record<string, unknown>
    try { parsed = text ? JSON.parse(text) : {} } catch { parsed = {} }
    const pick = (keys: string[]): string | null => {
      for (const k of keys) {
        const v = parsed[k]
        if (typeof v === 'string') {
          const s = v.trim()
          if (s.length > 0) return s
        }
        if (typeof v === 'number' && Number.isFinite(v)) {
          return String(v)
        }
      }
      return null
    }
    const _order_id = pick(['_order_id','orderId'])
    let customer_email = pick(['customer_email','customerEmail'])
    let customer_name = pick(['customer_name','customerName'])
    let order_number = pick(['order_number','orderNumber'])
    let carrier = pick(['carrier'])
    let tracking_number = pick(['tracking_number','trackingNumber'])
    let tracking_url = pick(['tracking_url','trackingUrl'])

    // Ensure env-derived flags are available before validation branches
    const testMode = Deno.env.get('EMAIL_TEST_MODE') === 'true'
    const testTo = Deno.env.get('EMAIL_TEST_TO') || 'delivered@resend.dev'

    // Derive fields from DB if not provided
    try {
      const supabaseUrl = Deno.env.get('SUPABASE_URL') || ''
      const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
      if (_order_id && supabaseUrl && serviceKey) {
        // Load order basics if needed
        if (!order_number || !customer_email || !customer_name || !carrier || !tracking_number || !tracking_url) {
          const sel = encodeURIComponent('user_id,order_number,carrier,tracking_number,tracking_url')
          const ordResp = await fetch(`${supabaseUrl}/rest/v1/venthub_orders?id=eq.${encodeURIComponent(_order_id)}&select=${sel}`, {
            headers: { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey }
          })
          if (ordResp.ok) {
            const arr = await ordResp.json().catch(()=>[])
            const row = Array.isArray(arr) ? arr[0] : null
            if (row) {
              if (!order_number && row.order_number) order_number = row.order_number
              if (!carrier && row.carrier) carrier = String(row.carrier)
              if (!tracking_number && row.tracking_number) tracking_number = String(row.tracking_number)
              if (!tracking_url && row.tracking_url) tracking_url = String(row.tracking_url)
              const uid = row.user_id as string | undefined
              if ((!customer_email || !customer_name) && uid) {
                // Use Auth Admin API to fetch user email securely with service role
                const usrResp = await fetch(`${supabaseUrl}/auth/v1/admin/users/${encodeURIComponent(uid)}`, {
                  headers: { Authorization: `Bearer ${serviceKey}`, apikey: serviceKey }
                })
                if (usrResp.ok) {
                  const u = await usrResp.json().catch(()=>null) as any
                  if (u) {
                    customer_email = customer_email || u.email || customer_email
                    // Try to read name from user_metadata
                    const metaName = (u.user_metadata && (u.user_metadata.full_name || u.user_metadata.name)) || null
                    customer_name = customer_name || metaName || customer_name
                  }
                }
              }
            }
          }
        }
      }
    } catch { /* best effort */ }

    // Validate required fields (after derivation)
    // In test mode, allow missing fields by auto-filling placeholders
    if (testMode) {
      if (!_order_id) _order_id = 'TEST-ORDER'
      if (!carrier) carrier = 'test-carrier'
      if (!tracking_number) tracking_number = 'T123'
      if (!customer_email) customer_email = testTo
    }

    if (!_order_id || !carrier || !tracking_number) {
      const missing: string[] = []
      if (!_order_id) missing.push('_order_id')
      if (!carrier) missing.push('carrier')
      if (!tracking_number) missing.push('tracking_number')
      return new Response(JSON.stringify({ 
        error: 'missing_fields',
        missing,
        received: Object.keys(parsed)
      }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      })
    }

    // Create email content
    const prettyOrderNo = order_number ? `#${String(order_number).split('-')[1]}` : `#${_order_id.slice(-8).toUpperCase()}`
    
    const brandName = Deno.env.get('BRAND_NAME') || 'VentHub'
    const brandPrimary = Deno.env.get('BRAND_PRIMARY_COLOR') || '#2563eb'
    const brandLogoUrl = Deno.env.get('BRAND_LOGO_URL') || ''

    const emailSubject = `${brandName} | Siparişiniz kargoya verildi - ${prettyOrderNo}`
    
    const emailContent = `
Merhaba ${customer_name},

${prettyOrderNo} numaralı siparişiniz kargoya verildi! 📦

🚛 Kargo Firması: ${carrier}
📋 Takip Numarası: ${tracking_number}
${tracking_url ? `🔗 Takip Linki: ${tracking_url}` : ''}

Siparişinizi takip edebilir ve teslimat durumunu kontrol edebilirsiniz.

Teşekkürler,
VentHub Ekibi

---
Bu otomatik bir e-postadır. Lütfen yanıtlamayın.
    `.trim()

    // (Info only) notification-service payload kept for reference; direct Resend is used below
    const _notificationRequest = {
      type: 'email',
      to: customer_email,
      message: emailContent,
      priority: 'medium',
      data: {
        subject: emailSubject,
        customer_name,
        order_number: prettyOrderNo,
        carrier,
        tracking_number,
        tracking_url
      }
    }

    const resendApiKey = Deno.env.get('RESEND_API_KEY')
    const emailFrom = Deno.env.get('EMAIL_FROM') || 'VentHub Test <onboarding@resend.dev>'
    const notifyDebug = Deno.env.get('NOTIFY_DEBUG') === 'true'
    const bccList = (Deno.env.get('SHIP_EMAIL_BCC') || 'recep.varlik@gmail.com').split(',').map(s=>s.trim()).filter(Boolean)
    if (!resendApiKey) {
      if (notifyDebug) console.warn('[shipping-notification] Email disabled: missing RESEND_API_KEY')
      return new Response(JSON.stringify({ success: true, disabled: true, channel: 'email' }), { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }

    // Build recipients with optional BCC; if no customer email, fall back to first BCC for testing
    const toList: string[] = []
    if (testMode) {
      toList.push(testTo)
    } else if (customer_email) {
      toList.push(customer_email)
    }
    const bcc = [...bccList]
    if (toList.length === 0 && bcc.length > 0) {
      toList.push(bcc[0])
      bcc.shift()
    }

    // Prepare HTML body: try file-based template, fallback to inline
    let htmlBody = ''
    try {
      const tpl = await loadShippingTemplate()
      if (tpl) {
        htmlBody = renderTemplate(tpl, {
          customer_name,
          order_number: prettyOrderNo,
          carrier,
          tracking_number,
          tracking_url,
          brand_name: brandName,
          brand_primary_color: brandPrimary,
          brand_logo_url: brandLogoUrl,
        })
      }
    } catch {/* ignore */}
    if (!htmlBody) {
      htmlBody = [
        '<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">',
        '<h2 style="color: #2563eb;">Siparişiniz kargoya verildi! 📦</h2>',
        `<p>Merhaba <strong>${customer_name}</strong>,</p>`,
        `<p><strong>${prettyOrderNo}</strong> numaralı siparişiniz kargoya verildi!</p>`,
        '<div style="background-color: #f8fafc; padding: 20px; border-radius: 8px; margin: 20px 0;">',
        '<h3 style="margin-top: 0; color: #374151;">Kargo Bilgileri</h3>',
        `<p><strong>🚛 Kargo Firması:</strong> ${carrier}</p>`,
        `<p><strong>📋 Takip Numarası:</strong> <code style="background-color: #e5e7eb; padding: 2px 6px; border-radius: 4px;">${tracking_number}</code></p>`,
        tracking_url ? `<p><strong>🔗 Takip Linki:</strong> <a href="${tracking_url}" target="_blank" style="color: #2563eb;">Kargo takip sayfası</a></p>` : '',
        '</div>',
        '<p>Siparişinizi takip edebilir ve teslimat durumunu kontrol edebilirsiniz.</p>',
        '<p>Teşekkürler,<br><strong>VentHub Ekibi</strong></p>',
        '<hr style="margin-top: 30px; border: none; border-top: 1px solid #e5e7eb;">',
        '<p style="color: #6b7280; font-size: 14px;">Bu otomatik bir e-postadır. Lütfen yanıtlamayın.</p>',
        '</div>'
      ].join('')
    }

    // Direct email sending (bypass notification-service for simplicity)
    async function sendEmail(fromAddr: string, to: string[], bccArr: string[]) {
      return await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${resendApiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          from: fromAddr,
          to,
          bcc: bccArr.length > 0 ? bccArr : undefined,
          subject: emailSubject,
          text: emailContent,
          html: htmlBody,
        }),
      })
    }

    // Try with configured from; if domain not verified, fallback to onboarding@resend.dev
    let response = await sendEmail(emailFrom, toList, bcc)
    if (!response.ok) {
      const errorText = await response.text()
      const normalized = errorText.toLowerCase()
      if (normalized.includes('domain') && normalized.includes('verify') || normalized.includes('from address')) {
        // Retry once with Resend test sender
        emailFrom = 'VentHub Test <onboarding@resend.dev>'
        response = await sendEmail(emailFrom, toList, bcc)
      }
      if (!response.ok) {
        try { await sentryCaptureException(new Error(`Email send failed: ${errorText}`), { fn: 'shipping-notification' }) } catch {}
        throw new Error(`Email send failed: ${errorText}`)
      }
    }

    const result = await response.json()

    // Best-effort audit insert; silent on failure
    try {
      const supabaseUrl = Deno.env.get('SUPABASE_URL') || ''
      const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
      if (supabaseUrl && serviceKey) {
        const payload = {
          _order_id,
          email_to: toList[0] || '',
          subject: emailSubject,
          provider: 'resend',
          provider_message_id: (result && result.id) || null,
          carrier: carrier || null,
          tracking_number: tracking_number || null
        }
        await fetch(`${supabaseUrl}/rest/v1/shipping_email_events`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${serviceKey}`, apikey: serviceKey, Prefer: 'return=minimal' },
          body: JSON.stringify(payload)
        })
      }
    } catch {}

    console.warn(`📧 Shipping notification sent to ${customer_email} for order ${prettyOrderNo}`)

    return new Response(JSON.stringify({ 
      success: true,
      result,
      _order_id,
      customer_email,
      subject: emailSubject,
      timestamp: new Date().toISOString()
    }), {
      status: 200,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    })

  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error ?? 'Unknown error')
    console.error('Shipping notification error:', msg)
    
    return new Response(JSON.stringify({ 
      error: msg,
      success: false 
    }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    })
  }
})

